def clean_text(value: str | None) -> str:
    if not value:
        return ""
    text = html.unescape(value)
    text = text.replace("\xa0", " ")
    text = re.sub(r"\s+", " ", text)
    text = re.sub(r"\bRussel\b", "Russell", text)
    return text.strip()


def clean_page_title(title: str) -> str:
    cleaned = clean_text(title)
    replacements = [
        (r"\bAI Thought experiment\b", "AI Thought Experiment"),
        (r"\bThought experiment\b", "Thought Experiment"),
        (r"^A Novel AI Thought Experiment\?$", "A Novel AI Thought Experiment"),
        (r"\bBertrand Russel\b", "Bertrand Russell"),
        (r"\bDialoguing with Russel\b", "Dialoguing with Russell"),
        (r"\bCharting Russel\b", "Charting Russell"),
    ]
    for pattern, replacement in replacements:
        cleaned = re.sub(pattern, replacement, cleaned)
    return cleaned


def has_unavailable_asset_reference(text: str) -> bool:
    lowered = clean_text(text).lower()
    return any(re.search(pattern, lowered) for pattern in UNAVAILABLE_ASSET_REFERENCE_PATTERNS)


def rewrite_curator_references(text: str) -> str:
    rewritten = clean_text(text)
    replacements = [
        (r"\bPhil[’']s\b", "the curator’s"),
        (r"\bPhil:\s*", "Curator: "),
        (r"\bPhil\b", "the curator"),
        (r"\bStilwell[’']s\b", "the curator’s"),
        (r"\bStilwell\b", "the curator"),
    ]
    for pattern, replacement in replacements:
        rewritten = re.sub(pattern, replacement, rewritten)
    rewritten = re.sub(r"\bthe curator who\b", "the curator, who", rewritten)
    rewritten = re.sub(r"\bbetween ([A-Z][A-Za-z0-9_-]+) and the curator\b", r"between \1 and the curator", rewritten)
    return clean_text(rewritten)


