def is_epistemology_foundation_page(page: dict, prompt: str = "") -> bool:
    if page["section_id"] != "epistemology":
        return False
    combined = f"{page['title']} {prompt}".lower()
    return any(marker in combined for marker in EPISTEMOLOGY_FOUNDATION_MARKERS)


def epistemology_foundation_paragraph(page: dict, prompt: str) -> str:
    topic = topic_label(page["title"])
    return (
        "This section should give the reader a usable epistemic lever: what would support the central claim, what would count against it, and what would make suspension of judgment more rational than either assent or denial. "
        f"The point is not to make {topic} tidy; it is to help the reader notice the difference between having a belief, having a reason, and having enough reason."
    )


def epistemology_foundation_items(page: dict, prompt: str) -> list[str]:
    topic = topic_label(page["title"])
    key = clean_discussion_key(short_prompt_key(prompt, topic), topic, "the claim")
    return [
        f"Borderline case: The reader should be able to say what would make {key} merely plausible rather than justified.",
        "Objection test: A strong section names the best reason a careful critic would withhold assent.",
        "Calibration test: The answer should distinguish certainty, high confidence, tentative belief, and responsible agnosticism.",
        f"Revision trigger: The page should identify what kind of new evidence would rationally change the reader's confidence about {topic}.",
    ]


def philosopher_expansion_paragraph(page: dict, prompt: str) -> str:
    topic = topic_label(page["title"])
    profile = philosopher_profile_for_title(page["title"])
    if profile:
        return (
            f"Read {topic} inside {profile['period']}, then ask what the method still forces later readers to notice. "
            f"{philosopher_method_sentence(profile)} "
            "The voice matters because the phrasing is often part of the philosophy: the reader should hear a way of thinking, not only collect a list of theses."
        )
