def targeted_section_expansion(page: dict, anchor: str) -> dict | None:
    return TARGETED_SECTION_EXPANSIONS.get((page.get("built_path", ""), anchor))


def targeted_section_heading(page: dict, anchor: str, default_heading: str) -> str:
    override = MANUAL_SECTION_HEADING_OVERRIDES.get((page.get("built_path", ""), anchor))
    if override:
        return clean_text(override)
    expansion = targeted_section_expansion(page, anchor)
    if expansion and expansion.get("heading"):
        return clean_text(expansion["heading"])
    return default_heading


def apply_targeted_section_expansion(
    page: dict,
    anchor: str,
    paragraphs: list[str],
    list_items: list[str],
) -> tuple[list[str], list[str], bool]:
    expansion = targeted_section_expansion(page, anchor)
    if not expansion:
        return paragraphs, list_items, False
    expanded_paragraphs = [] if expansion.get("replace_paragraphs") else list(paragraphs)
    for paragraph in expansion.get("paragraphs", []):
        append_unique_paragraph(expanded_paragraphs, paragraph)
    base_items = [] if expansion.get("replace_items") else list(list_items)
    expanded_items = dedupe(base_items + expansion.get("items", []))
    return expanded_paragraphs, expanded_items, True


def key_question_phrase(key_text: str) -> str:
    if key_text in {"this question", "the opening question", "the central question", "the central distinction"}:
        return key_text
    return f"the question about {key_text}"


def is_generic_sequence_key(key_text: str) -> bool:
    return key_text in {
        "the opening question",
        "the central question",
        "the central distinction",
        "the next pressure",
        "the previous step",
        "the next step",
        "this question",
    }


def rewrite_source_sentence(text: str) -> str:
    cleaned_full = remove_source_artifact_phrases(text)
    cleaned_full = re.sub(r"^(?:https?:)?//\S+\s*", "", cleaned_full).strip()
    replacements = [
        (r"^Yes,\s*", ""),
        (r"^Certainly,\s*", ""),
        (r"^Absolutely,\s*", ""),
        (r"^Of course,\s*", ""),
        (r"^Overall,\s*", ""),
        (r"^In essence,\s*", ""),
        (r"^Here[’']s\s+", ""),
        (r"^Here is\s+", ""),
        (r"\bI understand the intuition behind your question,?\s*[A-Z][a-z]+\.?", "the intuition behind the question is understandable."),
        (r"\b[Yy]ou[’']ve captured\b", "the formulation captures"),
        (r"\b[Yy]ou[’']ve articulated\b", "the formulation states"),
        (r"\b[Yy]our observations about\b", "the observations about"),
        (r"\b[Yy]our question touches\b", "the question touches"),
        (r"\b[Yy]our question delves into\b", "the question enters"),
        (r"\b[Yy]our question\b", "the question"),
        (r"\b[Yy]our two thoughtful prompts\b", "the two requested pressure points"),
        (r"\b[Yy]ou might have\b", "a reader might have"),
        (r"\b[Yy]ou can\b", "a reader can"),
        (r"\b[Yy]ou should\b", "a reader should"),
        (r"\b[Yy]ou[’']?re absolutely right[—-]?\s*", ""),
        (r"\b[Yy]ou[’']?re right to point out\b", "the objection rightly identifies"),
        (r"\b[Yy]ou[’']?re right(?:,|\b)\s*", ""),
        (r"\b[Yy]ou[’']?re correct(?:,|\b)\s*", ""),
        (r"\b[Yy]ou[’']?re highlighting\b", "the section highlights"),
        (r"\b[Yy]ou[’']?re sharpening the point beautifully\b", ""),
        (r"\b[Yy]our response appears circular\b", "the previous response appears circular"),
        (r"\b[Yy]our response is again circular\b", "the previous response is again circular"),
        (r"\b[Yy]ou response was circular\b", "the previous response was circular"),
        (r"\b[Yy]our response was circular\b", "the previous response was circular"),
        (r"\b[Yy]ou invoke\b", "the prior answer invokes"),
        (r"\b[Yy]ou refer to\b", "the prior answer refers to"),
        (r"\b[Yy]ou appeal to\b", "the prior answer appeals to"),
        (r"\b[Yy]our statement\b", "the prior statement"),
        (r"\byour are\b", "the prior answer is"),
        (r"\blike myself\b", "like AI systems"),
        (r"\bmyself\b", "the system itself"),
        (r"\bPlease try again\b", "the answer should be revised"),
        (r"\bI want to pushback on a few key points as follows\b", "the curator’s pushback focuses on several key points"),
        (r"\bI want to push back on a few key points as follows\b", "the curator’s pushback focuses on several key points"),
        (r"\bChatGPT says\b", "the prior answer says"),
        (r"\b[Yy]our pushback\b", "the pushback"),
        (r"\b[Yy]our position\b", "the curator’s position"),
        (r"\b[Yy]our perspective\b", "the position"),
        (r"\b[Yy]our point\b", "the point"),
        (r"\b[Yy]our argument\b", "the argument"),
        (r"\b[Yy]ou argue that\b", "the argument holds that"),
        (r"\b[Yy]ou argue\b", "the argument holds"),
        (r"\b[Yy]ou acknowledge\b", "the position acknowledges"),
        (r"\b[Yy]ou highlight\b", "the position highlights"),
        (r"\b[Yy]ou said\b", "the earlier formulation said"),
        (r"\bI frequently encounter\b", "the curator frequently encountered"),
        (r"\bdemands that I state whether they believe\b", "demands that the curator state whether a behavior is"),
        (r"\bI have\b", "the curator has"),
        (r"\bI[’']ll\b", "the response will"),
        (r"\bmy\b", "the curator's"),
        (r"\b[Ww]e[’']ve identified\b", "the discussion has identified"),
        (r"\b[Ww]e[’']ll use\b", "the model uses"),
        (r"\b[Oo]ur model\b", "the model"),
        (r"\b[Ll]et’s\b", "the response can"),
        (r"\b[Tt]he response can dive into\b", "the response examines"),
        (r"\b[Tt]he response can craft\b", "the response sketches"),
        (r"\b[Tt]he response can reframe\b", "the response reframes"),
        (r"\b[Tt]he response can apply\b", "the response applies"),
    ]

    def normalize_source_sentence(candidate: str) -> str:
        sentence = candidate
        label, body = split_label(sentence)
        if label and body:
            sentence = body
        for pattern, replacement in replacements:
            sentence = re.sub(pattern, replacement, sentence)
        sentence = rewrite_unavailable_asset_references(sentence)
        sentence = collapse_duplicate_function_words(sentence)
        sentence = re.sub(r"\s+([.,;:!?])", r"\1", sentence)
        sentence = re.sub(r"([.!?][”\"])\.", r"\1", sentence)
        sentence = compact_text(sentence, 280).strip()
        sentence = sentence.lstrip(" ,;:-")
        sentence = sentence.rstrip(" :;")
        return sentence

    if cleaned_full.startswith(("“", '"')):
        sentence_candidates = [cleaned_full]
    else:
        sentence_candidates = sentence_split(cleaned_full) or [cleaned_full]
        first_candidate = sentence_candidates[0]
        if (
            first_candidate.count("(") > first_candidate.count(")")
            or first_candidate.count("{") > first_candidate.count("}")
            or re.search(r"\b(P|Pr)\s*\([^)]*$", first_candidate)
        ):
            sentence_candidates = [cleaned_full]

    sentence = ""
    for candidate in sentence_candidates:
        normalized = normalize_source_sentence(candidate)
        plain = re.sub(r"<[^>]+>", " ", normalized)
        if len(clean_text(plain).strip(" ,;:-").split()) >= 4:
            sentence = normalized
            break
    if not sentence:
        sentence = normalize_source_sentence(cleaned_full)
    if sentence:
        sentence = sentence[0].upper() + sentence[1:]
    closed_quote_punctuation = sentence.endswith((".”", "!”", "?”", '."', '!"', '?"'))
    if sentence and sentence[-1] not in ".!?" and not closed_quote_punctuation:
        sentence += "."
    return sentence


def detail_has_source_material(detail: dict) -> bool:
    if detail.get("paragraphs") or detail.get("items") or detail.get("tables") or detail.get("dialogue_turns"):
        return True
    for child in detail.get("children", []):
        if child.get("paragraphs") or child.get("items"):
            return True
    return False


def should_keep_source_prompt_detail(detail: dict) -> bool:
    if detail_has_source_material(detail):
        return True
    prompt = clean_text(detail.get("prompt", ""))
    if not looks_like_prompt(prompt):
        return False
    if has_unavailable_asset_reference(prompt):
        return False
    return not re.search(
        r"\b(referenced source material|source material summarizes|referenced scenario|prior comparison)\b",
        prompt,
        flags=re.IGNORECASE,
    )


def extract_source_prompt_details(content_html: str, title: str) -> list[dict]:
    root = source_root(content_html)
    accepted_headings = source_prompt_heading_tags(content_html, title)
    if not accepted_headings:
        return []

    details: list[dict] = []
    for index, prompt_heading in enumerate(accepted_headings):
        next_prompt_heading = accepted_headings[index + 1] if index + 1 < len(accepted_headings) else None
        children: list[dict] = []
        paragraphs: list[str] = []
        items: list[str] = []
        tables: list[dict] = []
        dialogue_turns: list[dict] = []
        current_child: dict | None = None

        for element in prompt_heading.next_elements:
            if element is prompt_heading:
                continue
            if next_prompt_heading is not None and element is next_prompt_heading:
                break
            if not isinstance(element, Tag):
                continue

            if element.name and re.fullmatch(r"h[1-6]", element.name):
                text = strip_number_prefix(element.get_text(" ", strip=True))
                if not text or text == strip_number_prefix(prompt_heading.get_text(" ", strip=True)):
                    continue
                if (
                    looks_like_prompt(text)
                    and is_low_value_prompt(text)
                    and heading_level(element) <= heading_level(prompt_heading)
                ):
                    break
                if looks_like_prompt(text) and not is_low_value_prompt(text):
                    continue
                if is_low_value_heading(text) or is_low_value_prompt(text):
                    continue
                current_child = {"title": text, "level": heading_level(element), "paragraphs": [], "items": []}
                children.append(current_child)
                continue

            if element.name == "table":
                prior_heading = element.find_previous(["h3", "h2"])
                table_title = clean_text(prior_heading.get_text(" ", strip=True)) if prior_heading else ""
                if not table_title or looks_like_prompt(table_title):
                    table_title = "Structured comparison"
                parsed_table = extract_html_table(element, table_title, max_rows=10)
                if parsed_table:
                    tables.append(parsed_table)
                continue

            if element.name == "p":
                text = clean_text(element.get_text(" ", strip=True))
                lowered = text.lower()
                if len(text) < 65 or "table of contents" in lowered:
                    continue
                turn = parse_dialogue_turn_text(element.get_text("\n", strip=True))
                if turn:
                    dialogue_turns.append(turn)
                    continue
                target = current_child["paragraphs"] if current_child is not None else paragraphs
                target.append(text)
                continue

            if element.name == "li":
                text = clean_text(element.get_text(" ", strip=True))
                if len(text) < 45 or is_low_value_prompt(text):
                    continue
                turn = parse_dialogue_turn_text(element.get_text("\n", strip=True))
                if turn:
                    dialogue_turns.append(turn)
                    continue
                target = current_child["items"] if current_child is not None else items
                target.append(text)

        useful_children = []
        for child in children:
            if child["paragraphs"] or child["items"]:
                child["paragraphs"] = child["paragraphs"][:4]
                child["items"] = child["items"][:6]
                useful_children.append(child)

        details.append(
            {
                "prompt": clarify_prompt(prompt_heading.get_text(" ", strip=True)),
                "paragraphs": paragraphs[:4],
                "items": items[:8],
                "children": useful_children[:8],
                "tables": tables[:3],
                "dialogue_turns": dialogue_turns[:18],
            }
        )

    return details


def dedupe(items: Iterable[str]) -> list[str]:
    seen = set()
    result = []
    for item in items:
        if item and item not in seen:
            result.append(item)
            seen.add(item)
    return result


def branch_profile(section_id: str) -> dict:
    return BRANCH_PROFILES.get(section_id, DEFAULT_PROFILE)


def is_low_value_prompt(text: str) -> bool:
    lowered = clean_text(text).lower()
    return any(pattern in lowered for pattern in LOW_VALUE_PROMPT_PATTERNS) or any(
        re.search(pattern, lowered, flags=re.IGNORECASE) for pattern in LOW_VALUE_PROMPT_REGEXES
    )


def clarify_prompt(text: str) -> str:
    prompt = strip_number_prefix(text).strip(" :-")
    prompt = re.sub(r"\bthe entire thread above\b", "this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthe discussion above\b", "this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bcontent above\b", "this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthread above\b", "this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthe this discussion\b", "this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bbased on the this discussion\b", "based on this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\brelevant to the this discussion\b", "relevant to this discussion", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bdiscussion question\b", "discussion questions", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bProvide (\d+) discussion questions\b", r"Generate \1 discussion questions", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bCan we then safely say that is it likely that\b", "Can we safely say that it is likely that", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bis it likely that is it\b", "is it", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthe the\b", "the", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bto pushback\b", "to push back", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bPushback\b", "pushback", prompt)
    prompt = re.sub(r"\byour response to my request\b", "the prior response to the curator’s request", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour response appears circular\b", "the prior response appears circular", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour response is again circular\b", "the prior response is again circular", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byou response\b", "the prior response", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour response\b", "the prior response", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour responses\b", "the prior responses", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour statement\b", "the prior statement", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byou appeal to\b", "the prior answer appeals to", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byou invoke\b", "the prior answer invokes", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byou refer to\b", "the prior answer refers to", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour are\b", "the prior answer is", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bPlease try again\.?", "Revise the answer.", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\byour training data\b", "the AI’s training data", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bmy request\b", "the curator’s request", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\b1st-year\b", "first-year", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\brationality expert a novice\b", "rationality expert and a novice", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\ba Phenomenologists\b", "a phenomenologist", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\ban a\b", "a", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\battached philosophical writings\b", "selected philosophical writings", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthree attached writings\b", "three selected writings", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bthe attached\b", "the selected", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\battached\b", "selected", prompt, flags=re.IGNORECASE)
    prompt = re.sub(r"\bunevidence presupposition\b", "unevidenced presupposition", prompt, flags=re.IGNORECASE)
    prompt = re.sub(
        r"^In discussion on ethics,\s*I frequently encounter demands that I state whether they believe a behavior is [“\"]wrong[”\"]\.\s*But",
        "In ethical discussion, the curator frequently encounters demands to say whether a behavior is “wrong,” but",
        prompt,
        flags=re.IGNORECASE,
    )
    prompt = re.sub(
        r"^While I believe torturing cats is pragmatically wrong if you want people to like you, and is abhorred in most cultures, I do not believe it is morally wrong since I am a moral nihilist\.",
        "From a moral-nihilist standpoint, torturing cats may be pragmatically wrong if one wants social approval and culturally abhorred in most communities, yet not morally wrong.",
        prompt,
        flags=re.IGNORECASE,
    )
    prompt = rewrite_unavailable_asset_references(prompt)
    prompt = collapse_duplicate_function_words(prompt)
    if prompt:
        prompt = prompt[0].upper() + prompt[1:]
    return prompt


def curated_source_prompts(page: dict) -> list[str]:
    prompts = []
    for prompt in page.get("source_prompts", []):
        clarified = clarify_prompt(prompt)
        if not clarified or is_low_value_prompt(clarified):
            continue
        normalized = re.sub(r"[^a-z0-9]+", " ", clarified.lower()).strip()
        if any(normalized and normalized in re.sub(r"[^a-z0-9]+", " ", existing.lower()) for existing in prompts):
            continue
        prompts.append(clarified)
    return dedupe(prompts)[:5]


def topic_label(title: str) -> str:
    cleaned = clean_text(title)
    if cleaned in TOPIC_ALIASES:
        return TOPIC_ALIASES[cleaned]
    patterns = [
        r"^What is\s+",
        r"^What are\s+",
        r"^Dialoguing with\s+",
        r"^Charting\s+",
        r"^Dangers:\s+",
        r"^Case #\d+\s*[-–]\s*",
    ]
    for pattern in patterns:
        cleaned = re.sub(pattern, "", cleaned, flags=re.IGNORECASE)
    return cleaned.strip(" ?")


def philosopher_base_name(title: str) -> str:
    base = topic_label(title)
    if base in PHILOSOPHER_NAME_ALIASES:
        return PHILOSOPHER_NAME_ALIASES[base]

    normalized_base = re.sub(r"[^a-z0-9]+", " ", clean_text(base).lower()).strip()
    if normalized_base:
        for alias, canonical in PHILOSOPHER_NAME_ALIASES.items():
            alias_norm = re.sub(r"[^a-z0-9]+", " ", clean_text(alias).lower()).strip()
            if alias_norm and (
                normalized_base == alias_norm
                or normalized_base.startswith(f"{alias_norm} ")
            ):
                return canonical
        for canonical in PHILOSOPHER_PROFILES:
            canonical_norm = re.sub(r"[^a-z0-9]+", " ", clean_text(canonical).lower()).strip()
            if canonical_norm and (
                normalized_base == canonical_norm
                or normalized_base.startswith(f"{canonical_norm} ")
            ):
                return canonical

    return base


def philosopher_profile_for_title(title: str) -> dict | None:
    return PHILOSOPHER_PROFILES.get(philosopher_base_name(title))


def synthetic_philosopher_threads(title: str) -> list[str]:
    profile = philosopher_profile_for_title(title)
    if not profile:
        return []
    return [
        profile["signature"],
        profile["method"],
        *profile["concepts"],
        f"Central pressure: {profile['pressure']}",
        f"Influence trail: {profile['legacy']}",
    ]


def synthetic_child(title: str, paragraphs: list[str], items: list[str] | None = None) -> dict:
    return {
        "title": title,
        "level": 3,
        "paragraphs": paragraphs,
        "items": items or [],
    }


