def infer_kind(title: str, has_children: bool) -> str:
    lowered = clean_text(title).lower()
    if title in GROUP_PAGE_TITLES:
        return "special"
    if lowered.startswith("dialoguing with "):
        return "dialogue"
    if lowered.startswith("charting "):
        return "chart"
    if lowered.startswith("dangers:"):
        return "danger"
    if "core concepts" in lowered:
        return "core"
    if lowered.startswith("what is ") or lowered.startswith("what are "):
        return "concept"
    if has_children:
        return "cluster"
    if " vs " in lowered or " and " in lowered or "&" in title:
        return "comparison"
    return "essay"


def normalized_phrase(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", clean_text(text).lower()).strip()


def load_logfall_fallacies() -> list[dict]:
    if not LOGFALL_FALLACIES_PATH.exists():
        return []
    try:
        payload = json.loads(LOGFALL_FALLACIES_PATH.read_text())
    except json.JSONDecodeError:
        return []
    if not isinstance(payload, list):
        return []
    items = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        name = clean_text(item.get("name", ""))
        url = clean_text(item.get("url", ""))
        if name and url:
            items.append({"name": name, "url": url})
    return items


def logfall_alias_variants(alias: str) -> list[str]:
    variants = [alias]
    if "'" in alias:
        variants.append(alias.replace("'", "’"))
    if "’" in alias:
        variants.append(alias.replace("’", "'"))
    return dedupe([variant for variant in variants if variant])


def allow_generic_logfall_alias(alias: str) -> bool:
    normalized = normalized_phrase(alias)
    if not normalized:
        return False
    if normalized in BLOCKED_GENERIC_LOGFALL_ALIASES:
        return False
    words = normalized.split()
    if len(words) == 1:
        return normalized in SAFE_SINGLE_WORD_LOGFALL_ALIASES
    return words[-1] not in BLOCKED_GENERIC_LOGFALL_SUFFIX_WORDS


def build_logfall_link_catalog() -> tuple[dict[str, str], re.Pattern[str] | None]:
    canonical_entries = {item["name"]: item["url"] for item in load_logfall_fallacies()}
    aliases: dict[str, str] = {}
    raw_phrases: set[str] = set()

    def register(alias: str, target: str) -> None:
        if not alias:
            return
        url = canonical_entries.get(target, target)
        if not url:
            return
        for variant in logfall_alias_variants(clean_text(alias)):
            normalized = normalized_phrase(variant)
            if not normalized:
                continue
            aliases[normalized] = url
            raw_phrases.add(variant)

    for name, url in canonical_entries.items():
        register(name, url)
        lowered = name.lower()
        if not lowered.endswith(" fallacy"):
            register(f"{name} fallacy", url)
        if lowered.endswith(" argument"):
            stripped = clean_text(name[:-9])
            if allow_generic_logfall_alias(stripped):
                register(stripped, url)
        if lowered.endswith(" fallacy"):
            stripped = clean_text(name[:-8])
            if allow_generic_logfall_alias(stripped):
                register(stripped, url)

    manual_aliases = {
        "LogFall": LOGFALL_SITE_URL,
        "logfall.com": LOGFALL_SITE_URL,
        "logical fallacies": LOGFALL_ALL_FALLACIES_URL,
        "logical fallacy": LOGFALL_ALL_FALLACIES_URL,
        "common fallacies": LOGFALL_ALL_FALLACIES_URL,
        "list of fallacies": LOGFALL_ALL_FALLACIES_URL,
        "fallacy detection": LOGFALL_ALL_FALLACIES_URL,
        "false dichotomy": "False dilemma",
        "false dichotomies": "False dilemma",
        "strawman": "Straw man argument",
        "strawman fallacy": "Straw man argument",
        "straw man": "Straw man argument",
        "straw man fallacy": "Straw man argument",
        "straw man arguments": "Straw man argument",
        "strawman arguments": "Straw man argument",
        "appeal to popularity": "Argumentum ad populum",
        "appeal to the crowd": "Argumentum ad populum",
        "appeal to the people": "Argumentum ad populum",
        "ad populum": "Argumentum ad populum",
        "appeals to authority": "Appeal to authority",
        "appeals to emotion": "Appeal to emotion",
        "appeals to ignorance": "Argument from ignorance",
        "appeals to fear": "Appeal to fear",
        "appeals to ridicule": "Appeal to ridicule",
        "burden of proof": "Demanding negative proof",
        "shifting the burden of proof": "Demanding negative proof",
        "fallacy of division": "Division fallacy",
        "post hoc": "Post hoc ergo propter hoc",
        "post hoc fallacy": "Post hoc ergo propter hoc",
        "motive fallacy": "Appeal to motive",
        "deflecting to experts": "Appeal to authority",
        "false equivalencies": "False equivalence",
        "tu quoque or you too": "Tu quoque",
        "you too": "Tu quoque",
        "steppingstone fallacy": "Slippery slope",
        "the steppingstone fallacy": "Slippery slope",
        "gambler's fallacy": "Gambler's fallacy",
        "gambler’s fallacy": "Gambler's fallacy",
        "equivocation on wrong": "Equivocation",
        "correlation and causation": "Correlation is not causation",
    }
    for alias, target in manual_aliases.items():
        register(alias, target)

    if not aliases or not raw_phrases:
        return aliases, None
    escaped_phrases = [re.escape(phrase) for phrase in sorted(raw_phrases, key=len, reverse=True)]
    pattern = re.compile(rf"(?<![\w-])({'|'.join(escaped_phrases)})(?![\w-])", flags=re.IGNORECASE)
    return aliases, pattern


LOGFALL_LINKS_BY_PHRASE, LOGFALL_LINK_PATTERN = build_logfall_link_catalog()


def logfall_url_for_phrase(phrase: str) -> str | None:
    return LOGFALL_LINKS_BY_PHRASE.get(normalized_phrase(phrase))


def logfall_anchor_html(label: str, url: str) -> str:
    return (
        f'<a class="text-link" href="{html.escape(url)}" rel="noopener noreferrer">'
        f"{html.escape(label)}</a>"
    )


def inject_logfall_placeholders(text: str) -> tuple[str, dict[str, str]]:
    if not LOGFALL_LINK_PATTERN:
        return text, {}

    placeholders: dict[str, str] = {}

    if "https://en.wikipedia.org/wiki/List_of_fallacies" in text:
        key = f"__LOGFALL_LINK_{len(placeholders)}__"
        placeholders[key] = logfall_anchor_html("LogFall's fallacy index", LOGFALL_ALL_FALLACIES_URL)
        text = text.replace("https://en.wikipedia.org/wiki/List_of_fallacies", key)

    if not LOGFALL_LINK_PATTERN.search(text):
        return text, placeholders

    def replace(match: re.Match[str]) -> str:
        phrase = match.group(0)
        url = logfall_url_for_phrase(phrase)
        if not url:
            return phrase
        key = f"__LOGFALL_LINK_{len(placeholders)}__"
        placeholders[key] = logfall_anchor_html(phrase, url)
        return key

    replaced = LOGFALL_LINK_PATTERN.sub(replace, text)
    return replaced, placeholders


def slugfester_anchor_html(label: str = "Slugfester.com") -> str:
    return (
        f'<a class="text-link" href="{html.escape(SLUGFESTER_SITE_URL)}" rel="noopener noreferrer">'
        f"{html.escape(label)}</a>"
    )


def default_tag_label(tag: str) -> str:
    if tag in SECTION_META:
        return SECTION_META[tag]["name"]
    if tag in CONTROLLED_TAG_LABELS:
        return CONTROLLED_TAG_LABELS[tag]
    return clean_text(tag.replace("-", " ")).title()


def controlled_tag_meta() -> dict[str, dict]:
    meta: dict[str, dict] = {}
    for section_id, section in SECTION_META.items():
        meta[section_id] = {
            "label": section["name"],
            "kind": "branch",
            "aliases": [section["name"], section_id.replace("-", " ")],
        }
    for tag in sorted(PUBLIC_FORMAT_TAGS | CONTROLLED_TAG_EXTRA_KEYS | {item for section in SECTION_META.values() for item in section["futureTags"]}):
        aliases = [tag, tag.replace("-", " "), *CONTROLLED_TAG_ALIASES.get(tag, [])]
        if tag in meta and meta[tag]["kind"] == "branch":
            meta[tag]["aliases"] = dedupe(meta[tag]["aliases"] + aliases)
            continue
        meta[tag] = {
            "label": default_tag_label(tag),
            "kind": "format" if tag in PUBLIC_FORMAT_TAGS else "concept",
            "aliases": aliases,
        }
    return meta


CONTROLLED_TAG_META = controlled_tag_meta()


def curated_tag_vocabulary() -> set[str]:
    return set(CONTROLLED_TAG_META)


def tag_display_label(tag: str) -> str:
    return CONTROLLED_TAG_META.get(tag, {}).get("label", default_tag_label(tag))


def canonical_tag_key(raw_tag: str) -> str:
    normalized = normalized_phrase(raw_tag)
    if not normalized:
        return ""
    for tag, meta in CONTROLLED_TAG_META.items():
        aliases = [normalized_phrase(item) for item in meta.get("aliases", [])]
        if normalized in aliases:
            return tag
    return ""


def tag_alias_phrases(tag: str) -> list[str]:
    meta = CONTROLLED_TAG_META.get(tag)
    if not meta:
        return []
    phrases = []
    for alias in meta.get("aliases", []):
        normalized = normalized_phrase(alias)
        if normalized:
            phrases.append(normalized)
    return dedupe(phrases)


def matched_controlled_tags(text: str, allowed_kinds: set[str] | None = None) -> list[str]:
    normalized_text = normalized_phrase(text)
    if not normalized_text:
        return []
    matches: list[str] = []
    for tag, meta in CONTROLLED_TAG_META.items():
        if allowed_kinds and meta.get("kind") not in allowed_kinds:
            continue
        for phrase in tag_alias_phrases(tag):
            if re.search(rf"\b{re.escape(phrase)}\b", normalized_text):
                matches.append(tag)
                break
    return dedupe(matches)


def tag_signal_text(page: dict) -> str:
    parts = [
        page.get("title", ""),
        topic_label(page.get("title", "")),
        page.get("excerpt", ""),
        *page.get("source_prompts", [])[:4],
        *(detail.get("prompt", "") for detail in page.get("source_prompt_details", [])[:4]),
        *page.get("thread_like", [])[:6],
        *(child.get("title", "") for child in page.get("children", [])[:4]),
        *page.get("parent_titles", [])[:2],
    ]
    return " ".join(clean_text(part) for part in parts if clean_text(part))


def compound_tag_candidates(topic: str) -> tuple[list[str], set[str]]:
    normalized_topic = normalized_phrase(topic)
    phrase_tags: list[str] = []
    suppressed_components: set[str] = set()

    for phrase in sorted(COMPOUND_TAG_PHRASES, key=len, reverse=True):
        normalized = normalized_phrase(phrase)
        if not normalized:
            continue
        if not re.search(rf"\b{re.escape(normalized)}\b", normalized_topic):
            continue
        canonical = canonical_tag_key(normalized)
        if canonical:
            phrase_tags.append(canonical)
        suppressed_components.update(
            slugify(word)
            for word in normalized.split()
            if len(word) > 3
        )

    return dedupe(phrase_tags), suppressed_components


def tag_candidates(page: dict, section_meta: dict) -> list[str]:
    topic = topic_label(page["title"])
    phrase_tags, suppressed_components = compound_tag_candidates(topic)
    raw_title_terms = [
        slugify(word)
        for word in re.split(r"[\s/&:—–-]+", topic)
        if len(word) > 3 and slugify(word) not in suppressed_components
    ]
    title_tags = [canonical_tag_key(term) for term in raw_title_terms]
    matched_tags = matched_controlled_tags(tag_signal_text(page), {"concept"})
    seed_tags = [canonical_tag_key(tag) for tag in section_meta["futureTags"]]
    tags = dedupe(phrase_tags + title_tags + matched_tags + seed_tags)
    tags = [tag for tag in tags if tag and tag in curated_tag_vocabulary() and tag not in SECTION_IDS and tag not in PUBLIC_FORMAT_TAGS]
    return tags[:5]


def discovery_tag_candidates(page: dict, section_meta: dict) -> list[str]:
    """A compact, human-curated tag set for landing-page discovery."""
    tags: list[str] = [page["section_id"]]
    if page.get("kind") == "dialogue":
        tags.append("dialogue")
    elif page.get("kind") == "chart":
        tags.append("comparison")
    elif page.get("kind") == "cluster":
        tags.append("branch-map")
    elif clean_text(page.get("title", "")).lower().startswith(("what is ", "what are ")):
        tags.append("primer")

    page_tags = tag_candidates(page, section_meta)
    for tag in page_tags:
        if tag in curated_tag_vocabulary() and not re.match(r"^\d", tag) and is_discovery_safe_tag(tag):
            tags.append(tag)
    return dedupe(tags)[:7]


def is_discovery_safe_tag(tag: str) -> bool:
    normalized = clean_text(tag).lower()
    if len(normalized) < 3 or re.match(r"^\d", normalized):
        return False
    return normalized not in {
        "what",
        "when",
        "where",
        "whence",
        "with",
        "from",
        "that",
        "this",
        "into",
        "core",
        "case",
        "study",
        "red",
        "blue",
        "grey",
    }


def landing_signature_tag(section_id: str) -> str:
    for raw_tag in SECTION_META[section_id]["futureTags"]:
        tag = canonical_tag_key(raw_tag)
        if not tag or not is_discovery_safe_tag(tag):
            continue
        kind = CONTROLLED_TAG_META.get(tag, {}).get("kind")
        if kind == "format" or tag == section_id:
            continue
        return tag
    return ""


def build_landing_tags(tag_counts: dict[str, int]) -> list[str]:
    always_show = dedupe(["primer", "dialogue", "comparison", "branch-map", *SECTION_IDS])
    signature_tags = [landing_signature_tag(section_id) for section_id in SECTION_IDS]
    bridge_tags = [
        "evidence",
        "knowledge",
        "bias",
        "decision-making",
        "method",
        "inquiry",
    ]
    preferred = dedupe(always_show + signature_tags + bridge_tags)
    landing_tags = [
        tag
        for tag in preferred
        if tag
        and tag_counts.get(tag, 0)
        and is_discovery_safe_tag(tag)
    ]
    return landing_tags[:40]


def generic_standfirst(page: dict, section_meta: dict) -> str:
    topic = topic_label(page["title"])
    kind = page["kind"]
    profile = branch_profile(page["section_id"])
    article = "An" if section_meta["name"][:1].lower() in {"a", "e", "i", "o", "u"} else "A"
    if page["built_path"] == "/philosophical-inquiry/the-value-and-limits-of-debate/":
        return (
            "A Philosophical Inquiry page on debate, showing when public disagreement clarifies reasons, "
            "when it rewards performance, and how fallacies and cognitive biases distort the exchange."
        )
    if kind == "dialogue":
        return f"A philosopher dialogue page on {topic}, keeping the voice, tensions, and main lines of argument in clear prose."
    if kind == "chart":
        return f"A chart page on {topic}, mapping the main alignments, fault lines, and enduring contributions."
    if kind == "danger":
        return f"A cautionary page on {topic}, clarifying the appeal of the pattern and the epistemic costs it can impose."
    if kind == "cluster":
        return f"A branch page on {topic}, placing its nested posts inside {profile['standfirst']}"
    return f"{article} {section_meta['name']} page on {topic}, centered on {profile['standfirst']}"


def is_primer_page(page: dict) -> bool:
    lowered = clean_text(page.get("title", "")).lower()
    return lowered.startswith(("what is ", "what are "))


def page_form_label(page: dict) -> str:
    title = clean_text(page.get("title", ""))
    if page["kind"] == "dialogue":
        return "Dialogue page"
    if page["kind"] == "chart":
        return "Comparison chart"
    if page["kind"] == "danger":
        return "Caution page"
    if page["kind"] == "cluster":
        return "Branch cluster"
    if is_primer_page(page):
        return "Concept primer"
    if re.match(r"^Case\b", title, flags=re.IGNORECASE) or "case study" in title.lower():
        return "Case study"
    if "debate" in title.lower():
        return "Debate page"
    if page["section_id"] == "philosophers":
        return "Thinker profile"
    return "Guided essay"


def page_best_for(page: dict) -> str:
    if page["built_path"] == "/philosophical-inquiry/the-value-and-limits-of-debate/":
        return "reading public debate without mistaking rhetoric for inquiry"
    if page["kind"] == "dialogue":
        return "hearing a philosopher's method in motion"
    if page["kind"] == "chart":
        return "orientation by contrast before deeper reading"
    if page["kind"] == "danger":
        return "spotting seductive distortions before they harden"
    if page["kind"] == "cluster":
        return "seeing the branch map before choosing a path"
    if is_primer_page(page):
        return "first orientation to a major concept"
    return SECTION_SIGNAL_META.get(page["section_id"], {}).get(
        "best_for",
        "entering the topic with disciplined guidance",
    )


def page_difficulty_label(page: dict) -> str:
    base = SECTION_SIGNAL_META.get(page["section_id"], {}).get("difficulty", "Intermediate")
    if page["kind"] == "cluster":
        return "Foundational"
    if page["kind"] == "dialogue":
        return "Foundational to intermediate"
    if page["kind"] == "chart":
        return "Intermediate"
    if is_primer_page(page) and base == "Intermediate":
        return "Foundational to intermediate"
    return base


def render_page_signals(items: list[tuple[str, str, str | None]]) -> str:
    chips = []
    for label, value, href in items:
        clean_label = clean_text(label)
        clean_value = clean_text(value)
        if not clean_label or not clean_value:
            continue
        value_html = (
            f'<a href="{html.escape(href)}">{html.escape(clean_value)}</a>'
            if href
            else html.escape(clean_value)
        )
        chips.append(
            textwrap.dedent(
                f"""\
                    <li class="page-signals__item">
                      <span class="page-signals__label">{html.escape(clean_label)}</span>
                      <span class="page-signals__value">{value_html}</span>
                    </li>"""
            )
        )
    if not chips:
        return ""
    return textwrap.dedent(
        f"""\
              <ul class="page-signals" aria-label="Page signals">
        {chr(10).join(chips)}
              </ul>"""
    )


def article_page_signal_items(page: dict, prefix: str) -> list[tuple[str, str, str | None]]:
    section_meta = SECTION_META[page["section_id"]]
    branch_href = internal_article_href(prefix, branch_guide_path(page["section_id"]))
    return [
        ("Branch", section_meta["name"], branch_href),
        ("Page form", page_form_label(page), None),
        ("Best for", page_best_for(page), None),
        ("Difficulty", page_difficulty_label(page), None),
    ]


def archive_page_signal_items(
    *,
    scope: str,
    page_form: str,
    best_for: str,
    difficulty: str = "Foundational",
    scope_href: str | None = None,
) -> list[tuple[str, str, str | None]]:
    return [
        ("Scope", scope, scope_href),
        ("Page form", page_form, None),
        ("Best for", best_for, None),
        ("Difficulty", difficulty, None),
    ]


def feature_summary(page: dict, section_meta: dict) -> str:
    topic = topic_label(page["title"])
    if page["built_path"] == "/philosophical-inquiry/the-value-and-limits-of-debate/":
        return (
            "A guide to when debate clarifies a public question, when it degenerates into performance, "
            "and how fallacies and biases quietly steer the audience."
        )
    if page["kind"] == "dialogue":
        return f"A guided encounter with {topic} that keeps the philosopher’s voice, major claims, and main points of resistance in view."
    if page["kind"] == "chart":
        return f"A terrain map of {topic}, showing which themes, alignments, and tensions define the wider philosophical landscape."
    if page["kind"] == "danger":
        return f"A cautionary essay on {topic}, treating it as a recurring distortion that can quietly damage serious inquiry."
    return f"A page on {topic}, written to clarify its role inside the {section_meta['name']} branch."


def prompt_pack(page: dict, section_meta: dict) -> list[tuple[str, str]]:
    topic = page["title"]
    subject = topic_label(topic)
    source_prompts = curated_source_prompts(page)
    if source_prompts and page["kind"] not in {"dialogue", "chart"}:
        return [(f"prompt-{index}", prompt) for index, prompt in enumerate(source_prompts, start=1)]
    if page["kind"] == "dialogue":
        return [
            (anchor, dialogue_prompt_for_anchor(page, anchor))
            for anchor in ("voice-fragment", "beginner-dialogue", "deeper-dialogue", "critical-dialogue", "five-notions")
        ]
    if page["kind"] == "chart":
        return [
            ("orientation", f"Clarify the basic terrain one has to cross to understand {subject}."),
            ("threads", f"Identify the main alignments, commitments, and recurring themes associated with {subject}."),
            ("pressures", f"Highlight the strongest misalignments, criticisms, or points of tension surrounding {subject}."),
            ("discussion", f"Show what later readers should keep debating if they want the chart to remain philosophically alive."),
        ]
    if page["kind"] == "danger":
        return [
            ("orientation", f"Why does {subject} keep attracting human beings, even when it distorts careful inquiry?"),
            ("threads", f"How does {subject} typically operate once it settles into a community or worldview?"),
            ("pressures", f"What are the most serious intellectual and moral costs of normalizing {subject}?"),
            ("discussion", f"What disciplines or counter-habits best protect against {subject}?"),
        ]
    if page["kind"] == "cluster":
        return [
            ("orientation", f"What holds the {subject} cluster together as a recognizable branch or school?"),
            ("threads", f"Which sub-branches, figures, or internal divisions matter most inside {subject}?"),
            ("pressures", f"Where do the strongest tensions or disagreements appear inside {subject}?"),
            ("discussion", f"How should a reader begin moving through {subject} without losing the shape of the whole?"),
        ]
    prompts = source_prompts[:4]
    fallback = [
        f"What is most basically at stake in {subject}?",
        f"What distinctions or internal divisions matter most for understanding {subject} well?",
        f"Where is {subject} most often misunderstood, overstated, or misused?",
        f"What further questions naturally branch outward once {subject} is clarified?",
    ]
    chosen = dedupe(prompts + fallback)[:4]
    anchors = ["orientation", "threads", "pressures", "discussion"]
    return list(zip(anchors, chosen))


def render_paragraphs(parts: Iterable[str]) -> str:
    return "\n".join(f"              <p>{render_inline_text(part)}</p>" for part in parts if part)


def emphasize_escaped_phrase(rendered: str, phrase: str, tag: str) -> str:
    escaped_phrase = html.escape(phrase)
    pattern = re.compile(rf"(?<![\w-])({re.escape(escaped_phrase)})(?![\w-])", flags=re.IGNORECASE)
    return pattern.sub(lambda match: f"<{tag}>{match.group(1)}</{tag}>", rendered, count=1)


def render_inline_text(text: str, *, allow_links: bool = True) -> str:
    text = re.sub(r"\bMisalignment Elaboration\b", "misalignment comparisons", text)
    placeholders: dict[str, str] = {}
    if allow_links:
        text, placeholders = inject_logfall_placeholders(text)
    rendered = html.escape(text)
    rendered = re.sub(r"\*\*\s*(.+?)\s*\*\*", r"<strong>\1</strong>", rendered)
    rendered = rendered.replace("**", "")
    for phrase in sorted(INLINE_STRONG_PHRASES, key=len, reverse=True):
        rendered = emphasize_escaped_phrase(rendered, phrase, "strong")
    for phrase in sorted(INLINE_EMPHASIS_PHRASES, key=len, reverse=True):
        rendered = emphasize_escaped_phrase(rendered, phrase, "em")
    if allow_links:
        rendered = re.sub(
            r"(?<![\w/])(Credencing\.com|credencing\.com)(?![\w/])",
            f'<a class="text-link" href="{CREDENCING_SITE_URL}" rel="noopener noreferrer">Credencing.com</a>',
            rendered,
        )
        rendered = re.sub(
            r"(?<![\w/])(?:https?://)?(?:www\.)?(Slugfester\.com|slugfester\.com)(?![\w/])",
            slugfester_anchor_html(),
            rendered,
        )
        for placeholder, anchor_html in placeholders.items():
            rendered = rendered.replace(placeholder, anchor_html)
    return rendered


def format_thread_list(items: list[str]) -> str:
    if not items:
        return ""
    lis = "\n".join(f"                <li><strong>{html.escape(item)}:</strong> a live thread that helps organize the branch without exhausting it.</li>" for item in items[:6])
    return f"\n              <ol>\n{lis}\n              </ol>"


def discussion_thread_label(item: str, topic: str) -> str:
    label, _body = split_label(item)
    if label:
        return label
    if len(clean_text(item)) > 80:
        return short_prompt_key(item, topic)
    return item


def discussion_questions(page: dict, thread_like: list[str]) -> list[str]:
    topic = topic_label(page["title"])
    profile = branch_profile(page["section_id"])
    thread_like = usable_thread_items(thread_like)
    questions = list(page.get("quiz_discussion_items", []))[:3]
    questions.extend([
        f"Which distinction inside {topic} is easiest to miss when the topic is explained too quickly?",
        f"What is the strongest charitable reading of this topic, and what is the strongest criticism?",
        f"How does this page connect to {profile['lens']}?",
        f"What kind of evidence, argument, or lived pressure should most influence our judgment about {topic}?",
    ])
    if thread_like:
        thread_labels = [discussion_thread_label(item, topic) for item in thread_like[:3]]
        questions.append(f"Which of these threads matters most right now: {', '.join(thread_labels)}?")
    return dedupe(questions)[:5]


def serial_join(items: list[str]) -> str:
    cleaned = [clean_text(item) for item in items if clean_text(item)]
    if not cleaned:
        return ""
    if len(cleaned) == 1:
        return cleaned[0]
    if len(cleaned) == 2:
        return f"{cleaned[0]} and {cleaned[1]}"
    return f"{', '.join(cleaned[:-1])}, and {cleaned[-1]}"


def source_detail_labels(detail: dict | None) -> list[str]:
    if not detail:
        return []
    labels: list[str] = []
    for child in detail.get("children", []):
        label = rewrite_unavailable_asset_references(strip_number_prefix(child.get("title", "")))
        if label and source_label_is_heading_worthy(label):
            labels.append(label)
    for item in detail.get("items", []):
        label, body = split_label(item)
        if label and body and source_label_is_heading_worthy(label):
            labels.append(rewrite_unavailable_asset_references(label))
    return usable_thread_items(dedupe(labels))[:5]


def prompt_key_phrase(prompt: str, fallback: str) -> str:
    cleaned = clean_text(prompt)
    lowered = cleaned.lower()
    if "wrong" in lowered and any(term in lowered for term in ("equivocate", "semantically", "different contexts")):
        return "Equivocation over wrongness"
    if "wrong" in lowered and "pragmatically wrong" in lowered and "morally wrong" in lowered:
        return "Pragmatic, cultural, and moral wrongness"
    if "other terms" in lowered and "ethical" in lowered:
        return "Ethically loaded terms"
    key_phrases = [
        "adequate evidence",
        "anti-realism",
        "burden of proof",
        "critical thinking",
        "divine command theory",
        "epistemic switch",
        "gradient belief",
        "inductive substrate",
        "sub-absolute confidence",
        "inductive grounding",
        "instrumental value",
        "intuitionist logic",
        "justice",
        "moral realism",
        "moral non-realism",
        "moral intuitions",
        "moral landscape",
        "normative force",
        "outliers",
        "perverse incentives",
        "personal truth",
        "telephone game",
        "signal fidelity",
        "system fidelity",
        "logical fallacies",
        "training data bias",
        "self-evidence",
        "circularity",
        "human rights",
        "free will",
        "consciousness",
        "truth alignment",
        "wealth creation",
    ]
    for phrase in key_phrases:
        if phrase in lowered:
            return phrase[0].upper() + phrase[1:]

    command_patterns = [
        r"^assess the following statement against\s+(.+?)\.?$",
        r"^can you provide an actual scenario in which\s+(.+?)\.?$",
        r"^can you provide actual scenarios in which\s+(.+?)\.?$",
        r"^create a \d+-line dialogue between\s+(.+?)\.?$",
        r"^produce a \d+[- ]line hypothetical dialogue between\s+(.+?)\.?$",
        r"^produce a \d+[- ]line dialogue between\s+(.+?)\.?$",
        r"^create a hypothetical spirited dialogue between\s+(.+?)\.?$",
        r"^create a hypothetical dialogue between\s+(.+?)\.?$",
        r"^create a dialogue between\s+(.+?)\.?$",
        r"^create a short, rigorous paragraph highlighting\s+(.+?)\.?$",
        r"^create a table that displays\s+(.+?)\.?$",
        r"^create a table that, for each\s+(.+?)\s*,.+$",
        r"^create a table of\s+(.+?)\.?$",
        r"^how have findings in\s+(.+?)\s+led to\s+(.+?)\??$",
        r"^list the most influential\s+(.+?)\s+in history\.?$",
        r"^list and define \d+ key terms in\s+(.+?)\.?$",
        r"^list and provide clear explanations of \d+ key concepts in\s+(.+?)\.?$",
        r"^list and provide explanations of \d+ key concepts in\s+(.+?)\.?$",
        r"^list and describe new areas of interest in\s+(.+?)\.?$",
        r"^provide a short paragraph explaining\s+(.+?)\.?$",
        r"^provide a short definition of\s+(.+?)\.?$",
        r"^provide a short but clear definition of\s+(.+?)\.?$",
        r"^provide an annotated list of\s+(.+?)\.?$",
        r"^provide a comprehensive definition of\s+(.+?)\.?$",
        r"^provide a diverse list of\s+(.+?)\.?$",
        r"^provide a list of the key contributions\s+(.+?)\s+have made to philosophical thought\.?$",
        r"^provide a list of the key\s+(.+?)\s+have made to philosophical thought\.?$",
        r"^provide a list of resources relevant to\s+(.+?)\.?$",
        r"^provide a list that includes\s+(.+?)\.?$",
        r"^provide a list of books that someone should read if they want to study\s+(.+?)\.?$",
        r"^provide me with a list of\s+(.+?)\.?$",
        r"^provide the most likely causes behind\s+(.+?)\.?$",
        r"^provide the countries in\s+(.+?)\s+that are most stable politically today\.?$",
        r"^provide the universities in\s+(.+?)\s+that currently have the strongest programs in\s+(.+?)\.?$",
        r"^provide a salient description of the most critical issues within\s+(.+?)\s+today\.?$",
        r"^provide a salient description of the world of\s+(.+?)\s+today\.?$",
        r"^provide a timeline of the development of\s+(.+?)\.?$",
        r"^provide \d+ cases in which insights from\s+(.+?)\s+(?:has|have)\s+positively influenced\s+(.+?)\.?$",
        r"^provide \d+ actual cases in which a proxy was revealed to be improper\.?$",
        r"^provide a list of potential reasons .+? declined to answer this inquiry .+$",
        r"^provide a list of philosophers whose opinions would be off-limits .+$",
        r"^which universities currently have (?:the )?strong(?:est)? programs in\s+(.+?)\??$",
        r"^provide scores.+?for\s+(.+?)\.?$",
        r"^present a table showing\s+(.+?)\.?$",
        r"^using .+?, provide a table of\s+(.+?)\.?$",
        r"^create a table on\s+(.+?)\s+with columns.+$",
        r"^create a structured comparison showing\s+(.+?)\.?$",
        r"^create a quantitative account that\s+(.+?)\.?$",
        r"^can someone committed to the absence of objective free will also claim there is subjective free will\??$",
        r"^are deconversions of christians away from their faith into a commitment to rationality typically gradual or rapid\??.*$",
        r"^provide an explanation of induction that a \d+[- ]year[- ]old child could understand\.?$",
        r"^list fields of exploration similar to the drake equation in which there are cascading interdependent factors\.?$",
        r"^elaborate on\s+(.+?)\.?$",
        r"^explain\s+(.+?)\.?$",
    ]
    for pattern in command_patterns:
        match = re.match(pattern, cleaned, flags=re.IGNORECASE)
        if match:
            if pattern == r"^how have findings in\s+(.+?)\s+led to\s+(.+?)\??$":
                subject = match.group(1).strip()
                obj = match.group(2).strip()
                if "perceptions of value" in obj.lower():
                    candidate = f"perceived value through {subject}"
                else:
                    candidate = f"how {subject} changed {obj}"
            elif pattern == r"^provide a list of books that someone should read if they want to study\s+(.+?)\.?$":
                candidate = f"a reading route into {match.group(1)}"
            elif pattern == r"^provide a list of resources relevant to\s+(.+?)\.?$":
                candidate = f"resources relevant to {match.group(1)}"
            elif pattern == r"^provide the countries in\s+(.+?)\s+that are most stable politically today\.?$":
                candidate = f"political stability in {match.group(1)} today"
            elif pattern == r"^provide the universities in\s+(.+?)\s+that currently have the strongest programs in\s+(.+?)\.?$":
                candidate = f"strong programs in {match.group(2)}"
            elif pattern == r"^provide a salient description of the most critical issues within\s+(.+?)\s+today\.?$":
                candidate = f"the main issues in {match.group(1)}"
            elif pattern == r"^provide a salient description of the world of\s+(.+?)\s+today\.?$":
                candidate = f"{match.group(1)} today"
            elif pattern == r"^provide \d+ cases in which insights from\s+(.+?)\s+(?:has|have)\s+positively influenced\s+(.+?)\.?$":
                subject = match.group(1).strip()
                obj = match.group(2).strip()
                candidate = f"policy influence of {subject}"
                if obj.lower() not in {"policy", "policies"}:
                    candidate += f" on {obj}"
            elif pattern == r"^provide \d+ actual cases in which a proxy was revealed to be improper\.?$":
                candidate = "improper proxies in practice"
            elif pattern == r"^provide a list of potential reasons .+? declined to answer this inquiry .+$":
                candidate = "reasons an AI may refuse an inquiry"
            elif pattern == r"^provide a list of philosophers whose opinions would be off-limits .+$":
                candidate = "philosophers caught by censorship rules"
            elif pattern == r"^which universities currently have (?:the )?strong(?:est)? programs in\s+(.+?)\??$":
                candidate = f"strong programs in {match.group(1)}"
            elif pattern == r"^can someone committed to the absence of objective free will also claim there is subjective free will\??$":
                candidate = "subjective free will without objective free will"
            elif pattern == r"^are deconversions of christians away from their faith into a commitment to rationality typically gradual or rapid\??.*$":
                candidate = "how deconversion unfolds"
            elif pattern == r"^provide an explanation of induction that a \d+[- ]year[- ]old child could understand\.?$":
                candidate = "induction explained to a child"
            elif pattern == r"^list fields of exploration similar to the drake equation in which there are cascading interdependent factors\.?$":
                candidate = "drake-like cascading models across fields"
            else:
                candidate = match.group(1)
            candidate = compact_text(candidate, 90).rstrip(".")
            if candidate:
                return candidate[0].upper() + candidate[1:]

    quoted = re.findall(r"[“\"]([^”\"]{8,90})[”\"]", cleaned)
    if quoted:
        return quoted[0].strip()

    chunks = re.split(r"[.?;:—–-]", cleaned)
    chunks = [chunk.strip() for chunk in chunks if len(chunk.strip()) >= 24]
    if chunks:
        best = max(chunks[:4], key=len)
        if best.count("(") > best.count(")"):
            best = best.split("(", 1)[0].strip()
        return compact_text(best, 90).rstrip(".")
    return fallback


def source_prompt_heading(prompt: str, topic: str, detail: dict | None) -> str:
    key = short_prompt_key(prompt, topic)
    prompt_specific_heading = ""
    if key and key.lower() != topic.lower():
        prompt_specific_heading = article_native_heading(key, prompt, topic)

    labels = source_detail_labels(detail)
    if labels:
        center = ""
        for candidate in labels:
            candidate = candidate.strip(" .:")
            if candidate.lower() == topic.lower():
                continue
            if not is_low_value_heading(candidate):
                center = candidate
                break
        center = center or labels[0].strip(" .:")
        lowered_center = center.lower()
        if not (
            prompt_focus(prompt) == "inquiry"
            and any(term in lowered_center for term in ("example", "methodolog", "consideration", "context", "discussion", "question", "week", "objective", "program", "accessible"))
        ):
            label_heading = article_native_heading(center, prompt, topic)
            low_value_centers = {
                "articles",
                "australia",
                "books",
                "courses",
                "europe",
                "programs",
                "resources",
                "term",
                "terms",
                "universities",
            }
            if prompt_specific_heading and (
                label_heading == prompt_heading(prompt, topic)
                or is_generic_heading_for_topic(label_heading, topic)
                or clean_text(center).strip().lower() in low_value_centers
                or len(clean_text(center).split()) <= 2
            ) and not is_generic_heading_for_topic(prompt_specific_heading, topic):
                return prompt_specific_heading
            return label_heading

    if prompt_specific_heading:
        return prompt_specific_heading
    return prompt_heading(prompt, topic)


