def quiz_option(text: str, correct: bool, feedback: str) -> dict:
    return {
        "text": clean_text(text),
        "correct": correct,
        "feedback": clean_text(feedback),
    }


def quiz_section_terms(page: dict, sections: list[dict], section_meta: dict) -> list[str]:
    terms: list[str] = []
    generic_terms = {
        "best charitable version",
        "pressure point",
        "central distinction",
        "core claim",
        "summary",
        "conclusion",
        "questions",
    }
    for section in sections:
        for item in section.get("list_items", []) + section.get("question_items", []):
            label, body = split_label(item)
            candidate = label or body or item
            candidate = compact_text(strip_number_prefix(clean_text(candidate)).strip(" .:?"), 62)
            if (
                candidate
                and not is_source_artifact_label(candidate)
                and not looks_like_prompt(candidate)
                and not is_low_value_heading(candidate)
            ):
                terms.append(candidate)
    terms.extend(TOPIC_ITEMS.get(page["title"], []))
    terms.extend(page.get("thread_like", [])[:6])
    terms.extend(child["title"] for child in page.get("children", [])[:4])
    terms.extend(tag_candidates(page, section_meta)[:4])

    cleaned_terms: list[str] = []
    for term in terms:
        candidate = clean_text(term).strip(" .:?")
        if not candidate or len(candidate) < 4 or is_source_artifact_label(candidate):
            continue
        if candidate.lower() in generic_terms:
            continue
        if len(candidate.split()) > 9:
            candidate = compact_text(candidate, 68)
        cleaned_terms.append(candidate)
    return dedupe(cleaned_terms)[:8]


def quiz_context(page: dict, sections: list[dict], prompts: list[tuple[str, str]], section_meta: dict) -> dict:
    topic = topic_label(page["title"])
    profile = branch_profile(page["section_id"])
    prompt_sections = [section for section in sections if section.get("prompt")]
    first_section = prompt_sections[0] if prompt_sections else (sections[0] if sections else {})
    synthesis = next((section for section in sections if section.get("id") == "synthesis"), sections[-1] if sections else {})
    first_prompt = first_section.get("prompt") or (prompts[0][1] if prompts else "")
    first_key = short_prompt_key(first_prompt, topic) if first_prompt else topic
    terms = quiz_section_terms(page, sections, section_meta)
    branch_items = profile["items"]
    while len(terms) < 4:
        terms.append(branch_items[len(terms) % len(branch_items)])
    child_titles = [child["title"] for child in page.get("children", [])]
    sibling_titles = [title for title in page.get("sibling_titles", []) if title != page["title"]]

    return {
        "topic": topic,
        "branch": section_meta["name"],
        "profile": profile,
        "kind": page["kind"],
        "first_heading": clean_text(first_section.get("heading", "")) or f"{topic} needs disciplined interpretation.",
        "first_eyebrow": clean_text(first_section.get("eyebrow", "")) or "Orientation",
        "first_prompt": first_prompt,
        "first_key": first_key,
        "synthesis_heading": clean_text(synthesis.get("heading", "")) or "What ties this page together.",
        "synthesis_paragraph": compact_text(" ".join(synthesis.get("paragraphs", [])[:2]), 130),
        "terms": terms,
        "children": child_titles,
        "siblings": sibling_titles,
        "tags": tag_candidates(page, section_meta),
    }


def quiz_title_for_context(ctx: dict) -> str:
    topic = ctx["topic"]
    kind = ctx["kind"]
    if kind == "dialogue":
        return f"Check your understanding of {topic}"
    if kind == "chart":
        return f"Check your understanding of the {topic} map"
    if kind == "danger":
        return f"Check your understanding of the danger in {topic}"
    if kind == "cluster":
        return f"Check your understanding of {topic}"
    return f"Check your understanding of {topic}"


def quiz_focus_phrase(term: str) -> str:
    cleaned = clean_text(term).strip(" .:")
    lowered = cleaned.lower()
    words = cleaned.split()
    if words and words[-1].lower() in {"and", "or", "of", "to", "with", "for", "in", "the", "a", "an"}:
        cleaned = " ".join(words[:-1]).strip()
        lowered = cleaned.lower()
    if (
        not cleaned
        or len(cleaned.split()) > 7
        or lowered.startswith(("if ", "when ", "while ", "because ", "whether ", "which ", "what ", "how ", "why "))
        or re.search(r"\b(used the phrase|refers to|means that|is the|are the)\b", lowered)
        or "," in cleaned
    ):
        return "the central test case"
    return cleaned


def quiz_word_count(text: str) -> int:
    return len(clean_text(text).split())


def extend_quiz_option(text: str, addition: str) -> str:
    cleaned = clean_text(text).rstrip(" .;:")
    addition = clean_text(addition).strip()
    if not addition:
        return cleaned
    addition = addition[0].upper() + addition[1:]
    return clean_text(f"{cleaned}. {addition}")


def quiz_decoy_extension(ctx: dict, index: int) -> str:
    topic = ctx["topic"]
    terms = [quiz_focus_phrase(term) for term in ctx["terms"] if quiz_focus_phrase(term) != "a concrete example"]
    first = terms[0] if terms else topic
    second = terms[1] if len(terms) > 1 else ctx["branch"]
    extensions = [
        f"It leaves the page's contrast between {first} and {second} too blurry.",
        f"It treats {topic} mainly as a familiar label rather than a problem to interpret.",
        "It turns the page's pressure point into a simpler issue than the argument allows.",
        "It skips the harder question of how the page's distinctions guide judgment.",
        "It makes the answer sound tidy before the relevant tension has been faced.",
        "It would fit a quick summary better than a careful reading of the page.",
    ]
    return extensions[index % len(extensions)]


def quiz_correct_extension(ctx: dict, index: int) -> str:
    topic = ctx["topic"]
    terms = [quiz_focus_phrase(term) for term in ctx["terms"] if quiz_focus_phrase(term) != "a concrete example"]
    first = terms[0] if terms else topic
    extensions = [
        "That keeps the page from becoming a slogan.",
        "That keeps the main objection in view.",
        "That uses the distinction to guide judgment.",
        f"That avoids treating {topic} as already obvious.",
        f"That keeps {first} tied to the larger argument.",
    ]
    return extensions[index % len(extensions)]


def compact_quiz_answer(text: str) -> str:
    cleaned = clean_text(text)
    if quiz_word_count(cleaned) <= 30:
        return cleaned
    return compact_text(cleaned, 220)


def balance_quiz_item_options(item: dict, ctx: dict) -> dict:
    """Remove length as a visible tell for the correct quiz answer."""
    balanced_item = dict(item)
    options = [dict(option) for option in item.get("options", [])]
    if not options:
        balanced_item["options"] = options
        return balanced_item

    correct_indexes = [index for index, option in enumerate(options) if option.get("correct")]
    if not correct_indexes:
        balanced_item["options"] = options
        return balanced_item

    correct_index = correct_indexes[0]
    options[correct_index]["text"] = compact_quiz_answer(options[correct_index].get("text", ""))
    correct_words = quiz_word_count(options[correct_index]["text"])
    if correct_words < 10:
        options[correct_index]["text"] = extend_quiz_option(
            options[correct_index]["text"],
            quiz_correct_extension(ctx, correct_index),
        )
        correct_words = quiz_word_count(options[correct_index]["text"])

    for index, option in enumerate(options):
        if option.get("correct"):
            continue
        text = clean_text(option.get("text", ""))
        attempts = 0
        while quiz_word_count(text) < max(10, correct_words - 2) and attempts < 2:
            text = extend_quiz_option(text, quiz_decoy_extension(ctx, index + attempts))
            attempts += 1
        option["text"] = clean_text(text)

    lengths = [quiz_word_count(option.get("text", "")) for option in options]
    correct_words = lengths[correct_index]
    wrong_lengths = [
        lengths[index] for index, option in enumerate(options)
        if not option.get("correct")
    ]
    if (
        correct_words == min(lengths)
        and lengths.count(correct_words) == 1
        and wrong_lengths
        and min(wrong_lengths) - correct_words >= 2
    ):
        options[correct_index]["text"] = extend_quiz_option(
            options[correct_index]["text"],
            quiz_correct_extension(ctx, correct_index + 1),
        )
        lengths = [quiz_word_count(option.get("text", "")) for option in options]
        correct_words = lengths[correct_index]

    attempts = 0
    while correct_words == max(lengths) and lengths.count(correct_words) == 1 and attempts < 3:
        shortest_wrong = min(
            (index for index, option in enumerate(options) if not option.get("correct")),
            key=lambda index: quiz_word_count(options[index].get("text", "")),
            default=None,
        )
        if shortest_wrong is None:
            break
        options[shortest_wrong]["text"] = extend_quiz_option(
            options[shortest_wrong]["text"],
            quiz_decoy_extension(ctx, shortest_wrong + attempts + 4),
        )
        lengths = [quiz_word_count(option.get("text", "")) for option in options]
        attempts += 1

    balanced_item["options"] = options
    return balanced_item


def balance_quiz_options(quiz: dict, ctx: dict) -> dict:
    balanced_quiz = dict(quiz)
    balanced_quiz["items"] = [balance_quiz_item_options(item, ctx) for item in quiz.get("items", [])]
    return balanced_quiz


def central_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    branch = ctx["branch"]
    profile = ctx["profile"]
    kind = ctx["kind"]
    if kind == "dialogue":
        correct = (
            f"It shows {topic}'s voice and method in action, not just a list of beliefs."
        )
        question = f"What is this page mainly trying to help you understand?"
    elif kind == "chart":
        correct = (
            f"It maps the main parts of {topic} and the pressures between them."
        )
        question = f"What is the main purpose of this chart page?"
    elif kind == "cluster":
        correct = (
            f"It shows how the subtopics under {topic} belong together."
        )
        question = f"What is the main purpose of this branch page?"
    elif kind == "danger":
        correct = (
            f"It shows why {topic} is tempting and where it distorts inquiry."
        )
        question = f"What is this page mainly warning the reader about?"
    else:
        correct = (
            f"It clarifies what has to stay distinct about {topic}."
        )
        question = f"What is this page mainly trying to help you understand?"

    return {
        "question": question,
        "options": [
            quiz_option(correct, True, f"Correct. The page is not asking you merely to recognize {topic}. It is asking what the idea does, what it explains, and where it needs limits."),
            quiz_option("It gives a quick definition, and once the term is familiar, the main work is done.", False, "Not quite. A definition can be useful, but this page is doing more than vocabulary work. It asks what distinctions make the idea usable."),
            quiz_option("It asks the reader to choose the strongest-sounding side and defend it as quickly as possible.", False, "Not quite. Speed is not the virtue here. The page trains slower judgment about what should be separated, connected, or held open."),
            quiz_option("It gathers interesting related ideas, but does not ask how those ideas fit together.", False, "Not quite. A pile of related ideas is not yet understanding. The useful work is seeing which ideas are central and where confusion enters."),
        ],
    }


def focus_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    terms = ctx["terms"]
    focus = quiz_focus_phrase(terms[0])
    if ctx["kind"] == "dialogue":
        question = f"Why does the philosopher's voice matter here?"
        correct = (
            f"Because the style of exchange shows how {topic}'s view works."
        )
    elif ctx["kind"] == "chart":
        question = f"Why does the map format matter here?"
        correct = (
            f"Because the map keeps {topic}'s parts visible together."
        )
    else:
        question = f"Why does the page spend time on {focus}?"
        correct = (
            f"Because {focus} makes the stakes of {topic} concrete."
        )

    return {
        "question": question,
        "options": [
            quiz_option(correct, True, "Correct. This part of the page is doing work. It gives the reader something to use, not just a heading to remember."),
            quiz_option(f"Because it is a side note that can be skipped once the reader knows the basic definition.", False, "Not quite. The details are not garnish. They are how the page teaches the main idea without flattening it."),
            quiz_option(f"Because the page needs a place to mention more terms even if they do not affect the argument.", False, "Not quite. More terms do not help unless they sharpen a distinction, block a mistake, or clarify the pressure."),
            quiz_option(f"Because the page is mainly asking the reader to agree with its conclusion.", False, "Not quite. Agreement is too cheap. The better test is whether you can explain why the distinction matters."),
        ],
    }


def distinction_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    terms = ctx["terms"]
    phrases = []
    for term in terms:
        phrase = quiz_focus_phrase(term)
        if phrase not in phrases:
            phrases.append(phrase)
    fallback_phrases = [
        f"the main claim about {topic}",
        "the strongest objection",
        "the practical example",
        "the larger branch question",
    ]
    for phrase in fallback_phrases:
        if phrase not in phrases:
            phrases.append(phrase)
    first, second, third, fourth = phrases[:4]
    return {
        "question": f"Which reading habit would help most with this page?",
        "options": [
            quiz_option(f"Separate {first} from {second}, then ask how they relate.", True, "Correct. Many philosophical mistakes start by blending nearby ideas too early. Separate them first; then decide whether the connection is real."),
            quiz_option(f"Treat {first} as just another wording of {second}.", False, "Not quite. That may work casually, but the page is asking for more care. If two terms do different jobs, merging them weakens the argument."),
            quiz_option(f"Replace {third} and {fourth} with a general impression of what sounds reasonable.", False, "Not quite. General impressions can be useful starting points, but they are not enough here. The page asks the reader to track the actual distinctions."),
            quiz_option(f"Assume every idea near {topic} means about the same thing once the topic feels familiar.", False, "Not quite. Familiarity can hide confusion. A reader can feel comfortable with a topic while still missing the structure that makes it important."),
        ],
    }


def pressure_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    profile = ctx["profile"]
    return {
        "question": f"What mistake is this page trying to prevent?",
        "options": [
            quiz_option(f"Using {topic} as a shortcut instead of facing the harder question.", True, f"Correct. The harder question is this: {profile['pressure']} The quiz is testing whether you notice that pressure rather than retreating to the label."),
            quiz_option(f"Thinking the topic is too complex to discuss, so nothing useful can be said.", False, "Not quite. Complexity is not a reason to give up. It is a reason to use clearer distinctions and better examples."),
            quiz_option(f"Thinking the branch name already explains the page.", False, "Not quite. The branch name gives the page a home, but it does not explain the argument. The reader still has to see how the idea works."),
            quiz_option(f"Choosing the most comfortable interpretation and avoiding the parts that create tension.", False, "Not quite. The uncomfortable parts are often where the learning happens. This page is trying to keep those tensions visible."),
        ],
    }


def intermediate_reader_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    branch = ctx["branch"]
    return {
        "question": f"What would show real understanding of this page?",
        "options": [
            quiz_option(f"Stating the claim, naming a serious difficulty, and placing it inside {branch}.", True, "Correct. That is stronger than remembering a definition. It shows you understand the claim, the objection, and the larger setting."),
            quiz_option(f"The reader can quote the title and say whether they like the topic.", False, "Not quite. Personal reaction matters, but it is not enough. Understanding requires explaining what the page is doing and why the issue matters."),
            quiz_option("The reader can repeat a definition without explaining what problem the definition solves.", False, "Not quite. Definitions matter when they help us reason better. A repeated definition without a use is mostly verbal memory."),
            quiz_option(f"The reader can decide whether the page is persuasive before giving the argument a fair reconstruction.", False, "Not quite. Evaluation should come after charity. First make the view as clear and strong as the page allows; then judge it."),
        ],
    }


def misconception_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    term = quiz_focus_phrase(ctx["terms"][0])
    return {
        "question": f"Which response would miss the point of the page?",
        "options": [
            quiz_option(f"Assuming {topic} is clear because {term} already feels familiar.", True, "Correct. This is the shortcut the page resists. A familiar word can feel clear while still hiding the real philosophical issue."),
            quiz_option(f"Asking how the page's claim would change under a stronger objection.", False, "Not quite. That is usually a good move. Strong objections help reveal whether the argument has real strength or only surface appeal."),
            quiz_option(f"Connecting the page to nearby topics while still keeping the differences clear.", False, "Not quite. That is part of good reading. The archive depends on connection without careless merging."),
            quiz_option(f"Noticing when an attractive sentence needs a qualification.", False, "Not quite. Qualification is not a failure. It is often what keeps philosophical writing honest."),
        ],
    }


def future_branch_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    branch = ctx["branch"]
    neighbors = ctx["children"][:3] or ctx["siblings"][:3] or ctx["tags"][:3]
    neighbor_text = serial_join(neighbors) if neighbors else branch
    return {
        "question": f"Why does this page point to other pages?",
        "options": [
            quiz_option(f"Because nearby pages carry the same problem into related questions.", True, f"Correct. Here, useful next steps include {neighbor_text}. The links are not decoration; they show where the pressure continues."),
            quiz_option(f"Because every page should link elsewhere, even if the links do not add anything.", False, "Not quite. Links matter only when they help the reader think. Empty branching would make the archive busier but not wiser."),
            quiz_option(f"Because the archive structure is more important than the argument on the page.", False, "Not quite. The structure exists to support the argument. It should help the reader see relationships, not replace understanding."),
            quiz_option(f"Because future branches let the reader avoid deciding what this page itself claims.", False, "Not quite. A good branch does not postpone clarity. It gives the reader a way to carry clarity into the next question."),
        ],
    }


def synthesis_quiz_item(ctx: dict) -> dict:
    topic = ctx["topic"]
    synthesis = ctx["synthesis_heading"]
    synthesis_paragraph = ctx["synthesis_paragraph"]
    correct = f"It should change how the reader notices distinctions and tests claims about {topic}."
    feedback = (
        "Correct. This treats the synthesis as a tool for further thinking, not just a closing paragraph."
    )
    if synthesis_paragraph:
        feedback = f"{feedback} In the page's own terms, {synthesis_paragraph}"
    return {
        "question": f"What is the main lesson to carry away?",
        "options": [
            quiz_option(correct, True, feedback),
            quiz_option(f"The synthesis mainly means the page has reached its ending.", False, "Not quite. A synthesis should gather what has been learned. It is not just a polite way to stop talking."),
            quiz_option(f"The page's main value is that it removes future disagreement about {topic}.", False, "Not quite. Philosophical work often makes disagreement sharper and more responsible. It rarely makes all disagreement disappear."),
            quiz_option(f"The best takeaway is the sentence that can be turned into the neatest slogan.", False, "Not quite. A slogan may be memorable, but understanding requires seeing the moving parts behind it."),
        ],
    }


def generate_page_quiz(page: dict, sections: list[dict], prompts: list[tuple[str, str]], section_meta: dict) -> dict:
    ctx = quiz_context(page, sections, prompts, section_meta)
    return {
        "id": f"quiz-{slugify(ctx['topic']) or 'deep-understanding'}",
        "eyebrow": "Deep Understanding Quiz",
        "title": quiz_title_for_context(ctx),
        "intro": (
            "This quiz checks whether the main distinctions and cautions on the page are clear. "
            "Choose an answer, read the feedback, and click the question text if you want to reset that item."
        ),
        "items": [
            central_quiz_item(ctx),
            focus_quiz_item(ctx),
            distinction_quiz_item(ctx),
            pressure_quiz_item(ctx),
            intermediate_reader_quiz_item(ctx),
            misconception_quiz_item(ctx),
            future_branch_quiz_item(ctx),
            synthesis_quiz_item(ctx),
        ],
    }


def render_quiz_sections(
    page: dict,
    sections: list[dict] | None = None,
    prompts: list[tuple[str, str]] | None = None,
    section_meta: dict | None = None,
) -> str:
    section_meta = section_meta or SECTION_META[page["section_id"]]
    sections = sections or compose_sections(page)
    prompts = prompts or prompt_pack(page, section_meta)
    ctx = quiz_context(page, sections, prompts, section_meta)
    if page["built_path"] in QUIZ_OVERRIDES:
        quizzes = QUIZ_OVERRIDES[page["built_path"]]
    else:
        quizzes = [generate_page_quiz(page, sections, prompts, section_meta)]
    if not quizzes:
        return ""

    rendered_quizzes = []
    for quiz_index, quiz in enumerate(quizzes, start=1):
        quiz = balance_quiz_options(quiz, ctx)
        rendered_items = []
        for item_index, item in enumerate(quiz["items"], start=1):
            option_buttons = []
            option_order = list(item["options"])
            if option_order:
                shift = (item_index - 1) % len(option_order)
                option_order = option_order[shift:] + option_order[:shift]
            for option_index, option in enumerate(option_order):
                marker = chr(ord("A") + option_index)
                option_id = f"{quiz['id']}-q{item_index}-{marker.lower()}"
                option_state = "correct" if option["correct"] else "incorrect"
                option_buttons.append(
                    textwrap.dedent(
                        f"""\
                          <div class="quiz-choice">
                            <input
                              class="quiz-choice__input"
                              type="radio"
                              name="{html.escape(quiz['id'])}-q{item_index}"
                              id="{html.escape(option_id)}"
                            />
                            <label class="quiz-option quiz-option--{option_state}" for="{html.escape(option_id)}">
                              <span class="quiz-option__marker" aria-hidden="true">{marker}</span>
                              <span>{render_inline_text(option['text'])}</span>
                            </label>
                            <p class="quiz-feedback is-{option_state}" aria-live="polite">
                              {html.escape(option['feedback'])}
                            </p>
                          </div>"""
                    )
                )
            rendered_items.append(
                textwrap.dedent(
                    f"""\
                      <article class="quiz-item" data-quiz-item>
                        <div class="quiz-item__header">
                          <span class="quiz-item__number" aria-hidden="true">{item_index}</span>
                          <h3>
                            <button class="quiz-reset" type="button" data-quiz-reset title="Reset this question">
                              {render_inline_text(item['question'])}
                            </button>
                          </h3>
                        </div>
                        <fieldset class="quiz-options" aria-label="Question {item_index} options">
        {chr(10).join(option_buttons)}
                        </fieldset>
                      </article>"""
                )
            )

        rendered_quizzes.append(
            textwrap.dedent(
                f"""\
                    <section class="article-section quiz-section" id="{html.escape(quiz['id'])}" data-quiz>
                      <details class="quiz-accordion">
                        <summary>
                          <span class="quiz-section__badge" aria-hidden="true">Q</span>
                          <span class="quiz-accordion__title">
                            <span class="eyebrow">{html.escape(quiz['eyebrow'])}</span>
                            <span class="quiz-accordion__heading">{render_inline_text(quiz['title'])}</span>
                          </span>
                          <span class="quiz-accordion__cue" aria-hidden="true">+</span>
                        </summary>
                        <div class="quiz-accordion__body">
                          <p class="quiz-section__intro">{render_inline_text(quiz['intro'])}</p>
                          <div class="quiz-list">
        {chr(10).join(rendered_items)}
                          </div>
                      </div>
                      </details>
                    </section>"""
            )
        )

    return "\n".join(rendered_quizzes)


def page_gap_notes(page: dict, sections: list[dict]) -> list[str]:
    notes: list[str] = []
    quality_sections = [section for section in sections if section.get("quality")]
    gap_sections = [
        section
        for section in quality_sections
        if section["quality"].get("needsGapFill") or section["quality"].get("score", 100) < 94
    ]

    if page["section_id"] == "philosophers":
        child_titles = [child["title"] for child in page.get("children", [])]
        if page["kind"] == "dialogue":
            notes.append(
                "Future gap-fill: add one or two primary-source voice fragments, brief source context, and a sharper note on what the philosopher would resist in the reconstruction."
            )
        elif any(title.startswith(("Dialoguing with ", "Charting ")) for title in child_titles):
            notes.append(
                "Future gap-fill: build a compact philosopher dossier with a signature problem, historical setting, primary quote, strongest objection, and influence trail."
            )
        elif page["kind"] == "cluster":
            notes.append(
                "Future gap-fill: add connective school history so the nested philosopher links feel like an argument, not a seating chart for very intense dinner guests."
            )
        else:
            notes.append(
                "Future gap-fill: build a compact philosopher dossier with a signature problem, historical setting, primary quote, strongest objection, and influence trail."
            )

    if gap_sections:
        labels = ", ".join(section["id"].replace("prompt-", "Prompt ") for section in gap_sections[:4])
        notes.append(
            f"Exceptional-standard backlog: {labels} should eventually receive hand-selected examples, counterpressure, or source-specific detail beyond the generated scaffold."
        )

    sparse_count = sum(
        1
        for section in quality_sections
        if section["quality"]["metrics"]["labels"] <= 1 and section["quality"]["metrics"]["sourceParagraphs"] <= 1
    )
    if sparse_count and page["section_id"] != "philosophers":
        notes.append(
            f"Source scaffold note: {sparse_count} prompt section(s) have sparse recovered structure; later curation should add concrete cases before the page starts wearing a monocle and calling itself finished."
        )

    return dedupe(notes)[:4]


def internal_article_href(prefix: str, built_path: str) -> str:
    if not built_path:
        return ""
    if built_path == "/":
        return f"{prefix}index.html"
    return f"{prefix}{built_path.strip('/')}/"


def branch_guide_path(section_id: str) -> str:
    return f"/branches/{section_id}/"


def page_path_for_title(section_id: str, title: str) -> str:
    return RENDER_PAGE_PATHS_BY_SECTION_TITLE.get((section_id, clean_page_title(title)), "")


def breadcrumb_anchor(label: str, href: str) -> str:
    return f'<a href="{html.escape(href)}">{html.escape(label)}</a>'


def breadcrumb_trail_html(items: list[tuple[str, str]]) -> str:
    anchors = [breadcrumb_anchor(label, href) for label, href in items if label and href]
    return '<span>/</span>'.join(anchors)


def future_branch_link(title: str, built_path: str, prefix: str) -> str:
    escaped_title = html.escape(title)
    if not built_path:
        return f"<strong>{escaped_title}</strong>"
    return f'<a class="future-link" href="{html.escape(internal_article_href(prefix, built_path))}">{escaped_title}</a>'


def page_route_matches(page: dict) -> list[tuple[dict, int]]:
    current_path = normalize_site_path(page.get("built_path", ""))
    matches: list[tuple[dict, int]] = []
    for route in GUIDED_READING_PATHS:
        for index, step in enumerate(route.get("steps", [])):
            if normalize_site_path(step.get("path", "")) == current_path:
                matches.append((route, index))
    return matches


def reading_path_recommendations(page: dict) -> tuple[list[dict], list[dict]]:
    section_name = SECTION_META[page["section_id"]]["name"]
    section_id = page["section_id"]
    current_path = normalize_site_path(page.get("built_path", ""))
    seen_paths = {current_path}
    before: list[dict] = []
    after: list[dict] = []

    def add_item(bucket: list[dict], path: str, title: str, meta: str, reason: str) -> None:
        normalized = normalize_site_path(path)
        if not normalized or normalized in seen_paths:
            return
        if any(item["path"] == normalized for item in bucket):
            return
        bucket.append(
            {
                "path": normalized,
                "title": clean_text(title),
                "meta": clean_text(meta),
                "reason": clean_text(reason),
            }
        )
        seen_paths.add(normalized)

    parent_titles = page.get("parent_titles", [])
    if parent_titles:
        immediate_parent = parent_titles[-1]
        parent_path = page_path_for_title(section_id, immediate_parent)
        if parent_path:
            add_item(
                before,
                parent_path,
                immediate_parent,
                "Start wider",
                f"Start here if the current page feels compressed: {immediate_parent} gives the broader frame before the argument narrows into the present pressure.",
            )

    for route, index in page_route_matches(page):
        steps = route.get("steps", [])
        if index > 0 and page["section_id"] != "philosophers":
            previous = steps[index - 1]
            add_item(
                before,
                previous["path"],
                previous["title"],
                "Earlier step",
                f"In the route “{route['title']},” this page lands better after {previous['title']}, where the setup has already been clarified.",
            )

    if len(before) < 2:
        add_item(
            before,
            branch_guide_path(section_id),
            f"{section_name} Branch Guide",
            "Start with map",
            f"If this page feels abrupt, start with the {section_name} branch guide so the wider map is visible before the close reading begins.",
        )

    for child in page.get("children", [])[:3]:
        child_path = child.get("built_path") or page_path_for_title(section_id, child.get("title", ""))
        add_item(
            after,
            child_path,
            child.get("title", ""),
            "Go deeper",
            f"This page opens naturally into {child.get('title', '')}, where one of its subquestions is treated more directly.",
        )

    def add_route_follow_ups() -> None:
        for route, index in page_route_matches(page):
            steps = route.get("steps", [])
            if index < len(steps) - 1:
                following = steps[index + 1]
                add_item(
                    after,
                    following["path"],
                    following["title"],
                    "Next step",
                    f"In the route “{route['title']},” {following['title']} is the next useful move because it sharpens what this page leaves open.",
                )

    def add_sibling_follow_ups() -> None:
        sibling_titles = [title for title in page.get("sibling_titles", []) if title != page["title"]]
        for sibling_title in sibling_titles[:4]:
            sibling_path = page_path_for_title(section_id, sibling_title)
            add_item(
                after,
                sibling_path,
                sibling_title,
                "Nearby turn",
                f"{sibling_title} keeps the same branch pressure in view but turns it from a different angle.",
            )

    if page["section_id"] == "philosophers":
        add_sibling_follow_ups()
        add_route_follow_ups()
    else:
        add_route_follow_ups()
        add_sibling_follow_ups()

    if not after:
        add_item(
            after,
            branch_guide_path(section_id),
            f"{section_name} Branch Guide",
            "Return to map",
            f"If you want the wider continuation rather than a single next post, return to the {section_name} branch guide and choose the neighboring pressure that now feels most alive.",
        )

    return before[:2], after[:3]


def render_reading_path_cards(page: dict, prefix: str) -> str:
    before, after = reading_path_recommendations(page)
    if not before and not after:
        return ""

    def render_items(items: list[dict]) -> str:
        return "\n".join(
            textwrap.dedent(
                f"""\
                    <li class="reading-path-card__item">
                      <a class="reading-path-card__link" href="{html.escape(internal_article_href(prefix, item['path']))}">
                        {html.escape(item['title'])}
                      </a>
                      <p class="reading-path-card__meta">{html.escape(item['meta'])}</p>
                      <p class="reading-path-card__reason">{render_inline_text(item['reason'])}</p>
                    </li>"""
            )
            for item in items
        )

    return textwrap.dedent(
        f"""\
                  <section class="reading-path-grid" id="reader-route">
                    <article class="reading-path-card">
                      <p class="eyebrow">Read This First</p>
                      <h2>If this page feels abrupt, start here</h2>
                      <p class="reading-path-card__intro">These links provide the wider frame, earlier distinction, or branch map that makes the current page easier to enter.</p>
                      <ol class="reading-path-card__list">
        {render_items(before)}
                      </ol>
                    </article>
                    <article class="reading-path-card">
                      <p class="eyebrow">Read This Next</p>
                      <h2>If the page clicked, continue here</h2>
                      <p class="reading-path-card__intro">These are not just nearby pages. They are the strongest next moves if you want the pressure of this page to keep unfolding.</p>
                      <ol class="reading-path-card__list">
        {render_items(after)}
                      </ol>
                    </article>
                  </section>"""
    )


def tag_page_path(tag: str) -> str:
    return f"/tags/{slugify(tag)}/"


def tag_archive_link(tag: str, prefix: str) -> str:
    canonical = canonical_tag_key(tag) or tag
    label = tag_display_label(canonical)
    escaped_tag = html.escape(label)
    href = internal_article_href(prefix, tag_page_path(canonical))
    return (
        f'<a class="tag-chip" href="{html.escape(href)}" '
        f'aria-label="Show pages tagged {escaped_tag}">{escaped_tag}</a>'
    )


def link_static_tag_chips(target: Path) -> None:
    if not target.exists():
        return
    try:
        relative_parent = target.parent.relative_to(ROOT)
    except ValueError:
        return
    depth = 0 if str(relative_parent) == "." else len(relative_parent.parts)
    prefix = "../" * depth
    content = target.read_text()

    def replace_chip(match: re.Match[str]) -> str:
        raw_tag = match.group(1)
        tag = html.unescape(re.sub(r"<[^>]+>", "", raw_tag)).strip()
        if not tag:
            return match.group(0)
        return tag_archive_link(tag, prefix)

    updated = re.sub(r'<span class="tag-chip">([^<]+)</span>', replace_chip, content)

    def replace_old_tag_href(match: re.Match[str]) -> str:
        raw_tag = unquote(match.group(1)).strip()
        tag = canonical_tag_key(raw_tag) or raw_tag
        if not tag:
            return match.group(0)
        href = internal_article_href(prefix, tag_page_path(tag))
        return f'href="{html.escape(href)}"'

    updated = re.sub(
        r'href="[^"]*index\.html\?tag=([^"#]+)#tag-discovery"',
        replace_old_tag_href,
        updated,
    )
    if updated != content:
        target.write_text(updated)


def serial_join_html(items: list[str]) -> str:
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return f"{', '.join(items[:-1])}, and {items[-1]}"


def philosopher_original_framing(page: dict, philosopher: str) -> str:
    if page["kind"] == "dialogue":
        return (
            f"Newly written dialogue. The interlocutors and transitions are editorial, so {philosopher} can answer a live reader's questions without fake line-by-line ventriloquism."
        )
    if page["kind"] == "chart":
        return (
            "Newly written comparison page. The rows, headings, and contrasts are editorial, designed to turn a thinker into a usable map rather than a shrine with footnotes."
        )
    return (
        f"Newly written orientation page. The framing and prose are editorial, designed to make {philosopher} teachable without flattening the view into a slogan."
    )


def philosopher_preserved_texture(page: dict, philosopher: str, profile: dict | None) -> str:
    method_sentence = (
        philosopher_method_sentence(profile)
        if profile
        else "The page keeps the philosopher's characteristic motion of questioning, distinguishing, and pressing the issue."
    )
    if page["kind"] == "dialogue":
        return (
            f"What is being preserved is {philosopher}'s style under questioning. {method_sentence}"
        )
    if page["kind"] == "chart":
        return (
            f"What is being preserved is the philosopher's central pressure, strongest objection, and later influence in the same frame. {method_sentence}"
        )
    return (
        f"What is being preserved is the philosopher's characteristic way of proceeding, not just a pile of conclusions. {method_sentence}"
    )


def philosopher_ideas_in_view(philosopher: str, profile: dict | None) -> str:
    if profile and profile.get("concepts"):
        labels = [concept_label(concept) for concept in profile["concepts"][:4]]
        return serial_join(labels)
    return f"the signature problem, the governing method, the strongest objection, and the later influence trail around {philosopher}"


def render_philosopher_source_dossier(page: dict, philosopher: str, profile: dict | None, source_work: str) -> str:
    influence = profile["legacy"] if profile else f"the later debates that had to inherit, revise, or resist {philosopher}"
    setting = profile["period"] if profile else f"the historical setting that first made {philosopher}'s questions urgent"
    cards = [
        ("Original framing", philosopher_original_framing(page, philosopher)),
        ("Preserved texture", philosopher_preserved_texture(page, philosopher, profile)),
        ("Historical setting", setting),
        ("Primary texts nearby", source_work),
        ("Ideas in view", philosopher_ideas_in_view(philosopher, profile)),
        ("Influence trail", influence),
    ]
    card_html = "\n".join(
        textwrap.dedent(
            f"""\
                    <article class="source-dossier__card">
                      <p class="mini-label">{html.escape(label)}</p>
                      <p>{render_inline_text(text)}</p>
                    </article>"""
        )
        for label, text in cards
    )
    return textwrap.dedent(
        f"""\
              <div class="source-dossier">
{card_html}
              </div>"""
    )


def render_philosopher_source_texture_html(page: dict) -> str:
    if page["section_id"] != "philosophers":
        return ""
    profile = philosopher_profile_for_title(page["title"])

    philosopher = topic_label(page["title"])
    base = philosopher_base_name(page["title"])
    source_work = PHILOSOPHER_SOURCE_WORKS.get(base) or PHILOSOPHER_SOURCE_WORKS.get(philosopher) or "the primary texts, fragments, or source traditions associated with the thinker"
    dossier = render_philosopher_source_dossier(page, philosopher, profile, source_work)
    if profile:
        listening_for = (
            f"Read with one ear tuned to method and one eye on objection. {philosopher_method_sentence(profile)} "
            f"Do not merely collect positions; notice which distinction keeps forcing the page back to {profile['signature']}."
        )
    else:
        listening_for = (
            f"Read with one eye on historical setting and one eye on the point of resistance. The page should keep {philosopher} sounding like a pressure on thought rather than a wax museum label."
        )
    return textwrap.dedent(
        f"""\
            <section class="article-section article-section--source-texture" id="source-texture">
              <div class="article-section__meta">
                <p class="eyebrow">Source and Context</p>
              </div>
              <h2>Read {html.escape(philosopher)} with voice, context, and method in the same frame.</h2>
              <p>
                This dossier is here so the reader knows what has been newly framed on the page, what has been deliberately preserved, and which texts or ideas should stay nearby while the argument unfolds.
              </p>
{dossier}
              <p>
                {render_inline_text(listening_for)}
              </p>
            </section>"""
    )


def render_article_page(page: dict) -> str:
    section_meta = SECTION_META[page["section_id"]]
    prompts = prompt_pack(page, section_meta)
    sections = compose_sections(page)
    standfirst = generic_standfirst(page, section_meta)
    page_path = page["built_path"]
    depth = len(Path(page_path.strip("/")).parts)
    prefix = "../" * depth
    branch_path = branch_guide_path(page["section_id"])
    branch_href = internal_article_href(prefix, branch_path)
    page_signals = render_page_signals(article_page_signal_items(page, prefix))
    breadcrumbs = [
        ("Home", f"{prefix}index.html"),
        (section_meta["name"], branch_href),
        (page["title"], internal_article_href(prefix, page["built_path"])),
    ]
    prompt_index_by_anchor = {anchor: index for index, (anchor, _text) in enumerate(prompts, start=1)}
    prompt_text_by_anchor = {anchor: text for anchor, text in prompts}
    prompt_html = "\n".join(
        textwrap.dedent(
            f"""\
              <li>
                <a class="prompt-ledger__link" href="#{anchor}">
                  <span class="prompt-number" aria-hidden="true">{index}</span>
                  <span class="prompt-ledger__text">{render_inline_text(text, allow_links=False)}</span>
                </a>
              </li>"""
        )
        for index, (anchor, text) in enumerate(prompts, start=1)
    )

    body_parts = []
    credencing_note_added = False
    for section in sections:
        quality_attrs = ""
        prompt_number = prompt_index_by_anchor.get(section["id"])
        prompt_marker = ""
        section_class = "article-section"
        if prompt_number is not None:
            section_class += " article-section--prompt"
            prompt_marker = (
                f'                <span class="prompt-number article-section__number" '
                f'aria-hidden="true">{prompt_number}</span>\n'
            )
        prompt_text = section.get("prompt") or prompt_text_by_anchor.get(section["id"], "")
        prompt_note = ""
        if prompt_number is not None and prompt_text:
            prompt_note = (
                f'              <p class="article-section__prompt">'
                f'<span>Prompt {prompt_number}:</span> {render_inline_text(prompt_text)}</p>'
            )
        paragraphs = list(section.get("paragraphs", []))
        if not credencing_note_added and section_needs_credencing_resource(page, section, prompt_text):
            paragraphs.append(
                "For a companion resource on calibration, credence, and structured rational judgment, see Credencing.com."
            )
            credencing_note_added = True
        block = [
            f'            <section class="{section_class}" id="{section["id"]}"{quality_attrs}>',
            f'              <div class="article-section__meta">\n{prompt_marker}                <p class="eyebrow">{html.escape(section["eyebrow"])}</p>\n              </div>',
            prompt_note,
            f'              <h2>{render_inline_text(section["heading"])}</h2>',
            render_paragraphs(paragraphs),
        ]
        if section.get("dialogue_turns"):
            block.append(render_dialogue_card(section["dialogue_turns"], topic_label(page["title"])))
        if section.get("comparison_tables"):
            block.append(render_comparison_tables(section["comparison_tables"]))
        if section.get("list_items"):
            block.append(render_list_section(section["list_items"]))
        if section.get("question_items"):
            block.append(render_list_section(section["question_items"]))
        learning_items = section.get("learning_items") or pedagogical_checkpoints(
            page,
            prompt_text or section.get("heading", page["title"]),
            None,
        )
        if learning_items:
            block.append(render_learning_card(learning_items))
        block.append("            </section>")
        body_parts.append("\n".join(part for part in block if part))

    tags = discovery_tag_candidates(page, section_meta)
    tag_html = "\n".join(f"                {tag_archive_link(tag, prefix)}" for tag in tags)
    child_links = [
        future_branch_link(child["title"], child.get("built_path", ""), prefix)
        for child in page.get("children", [])[:6]
    ]
    sibling_titles = [title for title in page.get("sibling_titles", []) if title != page["title"]][:4]
    sibling_links = [
        future_branch_link(
            title,
            RENDER_PAGE_PATHS_BY_SECTION_TITLE.get((page["section_id"], clean_page_title(title)), ""),
            prefix,
        )
        for title in sibling_titles
    ]
    future_parts = []
    if child_links:
        future_parts.append(
            f"This branch opens directly into {serial_join_html(child_links)}, so the reader can move from the present argument into the next natural layer rather than treating the page as a dead end."
        )
    if sibling_links:
        future_parts.append(
            f"Nearby pages in the same branch include {serial_join_html(sibling_links)}; those links are not decorative, but suggested continuations where the pressure of this page becomes sharper, stranger, or more usefully contested."
        )
    if not future_parts:
        future_parts.append(
            f"This page belongs inside the wider <a class=\"future-link\" href=\"{html.escape(branch_href)}\"><strong>{html.escape(section_meta['name'])}</strong></a> branch and is best read in conversation with its neighboring topics. Future expansion should add direct neighboring links as the branch thickens."
        )
    future_paragraph = " ".join(future_parts)
    future_visual_html = ""
    future_panel_class = "future-branches-panel"
    if page["built_path"] == "/philosophical-inquiry/the-value-and-limits-of-debate/":
        future_paragraph += (
            f' For a live laboratory of public argument, visit {slugfester_anchor_html()}: '
            "watch how often logical fallacies and cognitive biases do more work than the stated reasons, "
            "and let the frequency of those patterns teach you something about the limits of debate as a truth engine."
        )
        future_panel_class += " future-branches-panel--with-visual"
        future_visual_html = (
            '                      <figure class="future-branches-visual future-branches-visual--slugfester">\n'
            f'                        <a href="{html.escape(SLUGFESTER_SITE_URL)}" rel="noopener noreferrer" aria-label="Visit Slugfester">\n'
            f'                          <img src="{prefix}assets/images/slugfester-debate-gloves.png" width="444" height="444" alt="Slugfester hanging boxing gloves representing public debate scorecards and argument analysis" loading="lazy" decoding="async" />\n'
            "                        </a>\n"
            "                        <figcaption>Slugfester turns public debate into a scored record of claims, fallacies, and bias pressure.</figcaption>\n"
            "                      </figure>"
        )
    if future_visual_html:
        future_body_html = (
            f'                      <div class="{future_panel_class}">\n'
            '                        <div class="future-branches-copy">\n'
            '                          <div class="tag-row">\n'
            f'        {tag_html}\n'
            '                          </div>\n'
            '                          <p>\n'
            f'                            {future_paragraph}\n'
            '                          </p>\n'
            '                        </div>\n'
            f"{future_visual_html}\n"
            "                      </div>"
        )
    else:
        future_body_html = (
            '                      <div class="tag-row">\n'
            f'        {tag_html}\n'
            '                      </div>\n'
            '                      <p>\n'
            f'                        {future_paragraph}\n'
            '                      </p>'
        )
    quiz_html = render_quiz_sections(page, sections, prompts, section_meta)
    quiz_block = f"\n\n{quiz_html}" if quiz_html else ""
    philosopher_texture = render_philosopher_source_texture_html(page)
    texture_block = f"\n\n{philosopher_texture}" if philosopher_texture else ""
    reading_path_block = render_reading_path_cards(page, prefix)
    reading_path_html = f"\n\n{reading_path_block}" if reading_path_block else ""
    page_url = absolute_site_url(page["built_path"])
    article_json = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": page["title"],
        "description": seo_description(standfirst),
        "url": page_url,
        "mainEntityOfPage": page_url,
        "image": absolute_site_url(SITE_IMAGE_PATH),
        "articleSection": section_meta["name"],
        "inLanguage": "en",
        "isPartOf": {"@type": "WebSite", "name": SITE_TITLE, "url": SITE_ORIGIN},
        "author": {"@type": "Organization", "name": "Byteseismic"},
        "publisher": {"@type": "Organization", "name": "Byteseismic"},
    }
    if page["built_path"] == "/philosophical-inquiry/the-value-and-limits-of-debate/":
        article_json["mentions"] = [
            {
                "@type": "WebSite",
                "name": "Slugfester",
                "url": SLUGFESTER_SITE_URL,
                "description": "Debate scorecards that surface argument structure, fallacies, and cognitive biases in public exchanges.",
            }
        ]
    if page.get("date"):
        article_json["datePublished"] = page["date"][:10]
    article_json["dateModified"] = BUILD_DATE.isoformat()
    article_head = render_seo_head(
        title=page["title"],
        description=standfirst,
        path=page["built_path"],
        prefix=prefix,
        page_type="article",
        section=section_meta["name"],
        extra_json_ld=[
            article_json,
            breadcrumb_json_ld(
                [
                    ("Home", "/"),
                    (section_meta["name"], branch_path),
                    (page["title"], page["built_path"]),
                ]
            ),
        ],
    )

    return textwrap.dedent(
        f"""\
        {AUTO_MARKER}
        <!DOCTYPE html>
        <html lang="en">
          <head>
            <meta charset="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
{article_head}
          </head>
          <body
            data-page-type="article"
            data-current-section="{page["section_id"]}"
            data-current-page="{page["built_path"]}"
          >
            <div class="page-shell" id="top">
              <header class="hero hero--article">
{render_hero_image(prefix)}
                <div class="hero__content">
                  <div class="breadcrumbs">
                    {breadcrumb_trail_html(breadcrumbs)}
                  </div>
                  <p class="hero__kicker">{html.escape(section_meta["name"])}</p>
                  <h1>{html.escape(page["title"])}</h1>
                  <p class="article-standfirst">
                    {render_inline_text(standfirst)}
                  </p>
{page_signals}
                </div>
              </header>

              <div class="article-layout article-layout--with-rail">
                <main class="article-stack">
                  <section class="prompt-ledger">
                    <p class="eyebrow">Prompts</p>
                    <h2>Prompts</h2>
                    <ol>
        {prompt_html}
                    </ol>
                  </section>

                  <div class="article-body">
        {texture_block}{reading_path_html}

        {'\n\n'.join(body_parts)}{quiz_block}

                    <section class="article-section" id="future-branches">
                      <p class="eyebrow">Future Branches</p>
                      <h2>Where this page naturally expands</h2>
{future_body_html}
                    </section>
                  </div>

                  <section class="article-outline-slot" data-article-outline></section>
                </main>
                <aside class="context-rail-slot" data-context-rail></aside>
              </div>
            </div>
          </body>
        </html>
        """
    )


