def inject_seo_into_manual_page(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or "<head>" not in existing or "</head>" not in existing:
        return False

    section_meta = SECTION_META[page["section_id"]]
    depth = len(Path(page["built_path"].strip("/")).parts)
    prefix = "../" * depth
    soup = BeautifulSoup(existing, "html.parser")
    existing_title = soup.find("title")
    existing_desc = soup.find("meta", attrs={"name": "description"})
    title_text = clean_text(existing_title.get_text(" ", strip=True)) if existing_title else page["title"]
    title_text = re.sub(r"\s+\|\s+Byteseismic(?: Reconstruction)?$", "", title_text)
    description = (
        clean_text(existing_desc.get("content", ""))
        if existing_desc and existing_desc.get("content")
        else generic_standfirst(page, section_meta)
    )
    page_url = absolute_site_url(page["built_path"])
    article_json = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": title_text,
        "description": seo_description(description),
        "url": page_url,
        "mainEntityOfPage": page_url,
        "image": absolute_site_url(SITE_IMAGE_PATH),
        "articleSection": section_meta["name"],
        "inLanguage": "en",
        "isPartOf": {"@type": "WebSite", "name": SITE_TITLE, "url": SITE_ORIGIN},
        "author": {"@type": "Organization", "name": "Byteseismic"},
        "publisher": {"@type": "Organization", "name": "Byteseismic"},
    }
    if page.get("date"):
        article_json["datePublished"] = page["date"][:10]
    article_json["dateModified"] = BUILD_DATE.isoformat()
    head = textwrap.dedent(
        f"""\
        <head>
            <meta charset="utf-8" />
            <meta name="viewport" content="width=device-width, initial-scale=1" />
        {render_seo_head(
            title=title_text,
            description=description,
            path=page["built_path"],
            prefix=prefix,
            page_type="article",
            section=section_meta["name"],
            extra_json_ld=[
                article_json,
                breadcrumb_json_ld(
                    [
                        ("Home", "/"),
                        (section_meta["name"], branch_guide_path(page["section_id"])),
                        (title_text, page["built_path"]),
                    ]
                ),
            ],
        ).lstrip()}
          </head>"""
    )
    updated = re.sub(r"<head>.*?</head>", head, existing, count=1, flags=re.DOTALL)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def inject_page_signals_into_manual_page(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    depth = len(Path(page["built_path"].strip("/")).parts)
    prefix = "../" * depth
    signals_html = render_page_signals(article_page_signal_items(page, prefix))
    if not signals_html:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    hero_content = soup.select_one(".hero__content")
    if hero_content is None:
        return False

    fragment = BeautifulSoup(signals_html, "html.parser")
    replacement = fragment.select_one(".page-signals")
    if replacement is None:
        return False

    existing_signals = hero_content.select_one(".page-signals")
    if existing_signals is not None:
        existing_signals.replace_with(replacement)
    else:
        standfirst = hero_content.select_one(".article-standfirst")
        if standfirst is not None:
            standfirst.insert_after(replacement)
        else:
            hero_content.append(replacement)

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def inject_philosopher_source_texture_into_manual_page(target: Path, page: dict) -> bool:
    if page["section_id"] != "philosophers" or not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    source_texture_html = render_philosopher_source_texture_html(page)
    if not source_texture_html:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    article_body = soup.select_one(".article-body")
    if not article_body:
        return False

    fragment = BeautifulSoup(source_texture_html, "html.parser")
    source_section = fragment.select_one("#source-texture")
    if source_section is None:
        return False

    existing_source = article_body.select_one("#source-texture")
    if existing_source is not None:
        existing_source.replace_with(source_section)
    else:
        first_section = article_body.find("section", recursive=False)
        if first_section is not None:
            first_section.insert_before(source_section)
        else:
            article_body.append(source_section)

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def normalize_manual_prompt_system(target: Path) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    ledger = soup.select_one(".prompt-ledger")
    article_body = soup.select_one(".article-body")
    if not ledger or not article_body:
        return False

    ledger_items = ledger.select("ol > li")
    if not ledger_items:
        return False

    sections = [
        section
        for section in article_body.find_all("section", recursive=False)
        if "quiz-section" not in (section.get("class") or [])
        and section.get("id") not in {"future-branches"}
        and "process-note" not in (section.get("class") or [])
    ]
    claimed_section_ids: set[str] = set()
    changed = False

    for index, item in enumerate(ledger_items, start=1):
        existing_link = item.find("a")
        existing_text = existing_link.select_one(".prompt-ledger__text") if existing_link else None
        prompt_text = clean_text(
            existing_text.get_text(" ", strip=True)
            if existing_text
            else existing_link.get_text(" ", strip=True)
            if existing_link
            else item.get_text(" ", strip=True)
        )
        prompt_text = re.sub(rf"^\s*{index}\s+", "", prompt_text)
        href = clean_text(existing_link.get("href", "")) if existing_link else ""

        target_section = None
        if href.startswith("#"):
            target_section = article_body.find(id=href[1:])
            if target_section is not None and target_section.get("id") in claimed_section_ids:
                item.decompose()
                changed = True
                continue
        if target_section is None:
            for candidate in sections:
                if candidate.get("id"):
                    if candidate["id"] in claimed_section_ids:
                        continue
                    target_section = candidate
                    href = f"#{candidate['id']}"
                    break
        if target_section is None:
            item.decompose()
            changed = True
            continue
        if target_section.get("id"):
            claimed_section_ids.add(target_section["id"])

        target_classes = target_section.get("class") or []
        if "article-section--prompt" not in target_classes:
            target_section["class"] = [*target_classes, "article-section--prompt"]
            changed = True

        item.clear()
        link = soup.new_tag("a", href=href)
        link["class"] = "prompt-ledger__link"
        number = soup.new_tag("span")
        number["class"] = "prompt-number"
        number["aria-hidden"] = "true"
        number.string = str(index)
        text_span = soup.new_tag("span")
        text_span["class"] = "prompt-ledger__text"
        text_span.string = prompt_text
        link.append(number)
        link.append(text_span)
        item.append(link)
        changed = True

        direct_eyebrow = target_section.find("p", class_="eyebrow", recursive=False)
        meta = target_section.find("div", class_="article-section__meta", recursive=False)
        if meta is None and direct_eyebrow is not None:
            meta = soup.new_tag("div")
            meta["class"] = "article-section__meta"
            direct_eyebrow.insert_before(meta)
            direct_eyebrow.extract()
            meta.append(direct_eyebrow)
            changed = True
        if meta is not None:
            old_number = meta.select_one(".article-section__number.prompt-number")
            if old_number is None:
                section_number = soup.new_tag("span")
                section_number["class"] = "prompt-number article-section__number"
                section_number["aria-hidden"] = "true"
                section_number.string = str(index)
                meta.insert(0, section_number)
                changed = True
            elif clean_text(old_number.get_text()) != str(index):
                old_number.string = str(index)
                changed = True

        prompt_note = target_section.find("p", class_="article-section__prompt", recursive=False)
        desired_label = f"Prompt {index}:"
        if prompt_note is None:
            prompt_note = soup.new_tag("p")
            prompt_note["class"] = "article-section__prompt"
            label = soup.new_tag("span")
            label.string = desired_label
            prompt_note.append(label)
            prompt_note.append(f" {prompt_text}")
            insert_after = meta or target_section.find(["p", "h2"], recursive=False)
            if insert_after is not None:
                insert_after.insert_after(prompt_note)
            else:
                target_section.insert(0, prompt_note)
            changed = True
        else:
            prompt_note.clear()
            label = soup.new_tag("span")
            label.string = desired_label
            prompt_note.append(label)
            prompt_note.append(f" {prompt_text}")
            changed = True

    if not changed:
        return False

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def normalize_manual_breadcrumbs(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    trail = soup.select_one(".hero .breadcrumbs") or soup.select_one(".breadcrumbs")
    if trail is None:
        return False

    depth = len(Path(page["built_path"].strip("/")).parts)
    prefix = "../" * depth
    section_meta = SECTION_META[page["section_id"]]
    branch_href = internal_article_href(prefix, branch_guide_path(page["section_id"]))
    title_text = page.get("title") or clean_text((soup.find("h1") or trail).get_text(" ", strip=True))

    replacement = BeautifulSoup(
        textwrap.dedent(
            f"""\
            <div class="breadcrumbs">
              <a href="{html.escape(prefix)}index.html">Home</a>
              <span>/</span>
              <a href="{html.escape(branch_href)}">{html.escape(section_meta["name"])}</a>
              <span>/</span>
              <span>{html.escape(title_text)}</span>
            </div>"""
        ),
        "html.parser",
    ).div
    if replacement is None:
        return False

    current_markup = "".join(str(child) for child in trail.contents).strip()
    replacement_markup = "".join(str(child) for child in replacement.contents).strip()
    if current_markup == replacement_markup:
        return False

    trail.replace_with(replacement)
    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def manual_section_detail(section: Tag) -> dict:
    detail: dict = {
        "paragraphs": [],
        "items": [],
        "children": [],
        "tables": [],
        "dialogue_turns": [],
    }

    for paragraph in section.find_all("p"):
        if paragraph.find_parent(class_="learning-card"):
            continue
        classes = paragraph.get("class") or []
        if "eyebrow" in classes or "article-section__prompt" in classes or "learning-card__title" in classes:
            continue
        text = clean_text(paragraph.get_text(" ", strip=True))
        if text:
            detail["paragraphs"].append(text)

    for item in section.find_all("li"):
        if item.find_parent(class_="learning-card"):
            continue
        text = clean_text(item.get_text(" ", strip=True))
        if text:
            detail["items"].append(text)

    for heading in section.find_all(["h3", "h4"]):
        text = clean_text(heading.get_text(" ", strip=True))
        if text:
            detail["children"].append({"title": text, "paragraphs": [], "items": []})

    for turn in section.select(".dialogue-turn"):
        speaker = turn.select_one(".dialogue-turn__speaker")
        body = turn.find("p")
        speaker_text = clean_text(speaker.get_text(" ", strip=True) if speaker else "")
        body_text = clean_text(body.get_text(" ", strip=True) if body else "")
        if speaker_text and body_text:
            detail["dialogue_turns"].append({"speaker": speaker_text, "text": body_text})

    for table in section.find_all("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.find_all("th")]
        rows = []
        for row in table.find_all("tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in row.find_all("td")]
            if cells:
                rows.append(cells)
        if headers or rows:
            detail["tables"].append({"headers": headers, "rows": rows})

    return detail


def inject_learning_cards_into_manual_page(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    article_body = soup.select_one(".article-body")
    if not article_body:
        return False

    changed = False
    for section in article_body.find_all("section", recursive=False):
        section_classes = section.get("class") or []
        if "article-section--prompt" not in section_classes:
            continue
        if "quiz-section" in section_classes or section.get("id") in {"future-branches"}:
            continue
        existing_card = section.select_one(".learning-card")
        if existing_card is not None:
            existing_card.decompose()

        prompt_note = section.find("p", class_="article-section__prompt", recursive=False)
        heading = section.find("h2", recursive=False)
        prompt_text = clean_text(prompt_note.get_text(" ", strip=True) if prompt_note else "")
        prompt_text = re.sub(r"^Prompt\s+\d+\s*:\s*", "", prompt_text, flags=re.IGNORECASE)
        if not prompt_text and heading is not None:
            prompt_text = clean_text(heading.get_text(" ", strip=True))
        if not prompt_text:
            prompt_text = f"Clarify the teaching pressure inside {page['title']}."

        detail = manual_section_detail(section)
        card_fragment = BeautifulSoup(
            render_learning_card(pedagogical_checkpoints(page, prompt_text, detail)),
            "html.parser",
        )
        card = card_fragment.select_one(".learning-card")
        if card is None:
            continue

        insert_after = None
        for candidate in reversed(section.find_all(["ol", "ul", "div", "p"], recursive=False)):
            if "article-section__prompt" in (candidate.get("class") or []):
                continue
            insert_after = candidate
            break
        if insert_after is not None:
            insert_after.insert_after(card)
        else:
            section.append(card)
        changed = True

    if not changed:
        return False

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def inject_reading_path_into_manual_page(target: Path, page: dict) -> bool:
    if not target.exists():
        return False
    existing = target.read_text()
    if AUTO_MARKER in existing or 'data-page-type="article"' not in existing:
        return False

    depth = len(Path(page["built_path"].strip("/")).parts)
    prefix = "../" * depth
    reading_path_html = render_reading_path_cards(page, prefix)
    if not reading_path_html:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    article_body = soup.select_one(".article-body")
    if not article_body:
        return False

    existing_block = article_body.select_one("#reader-route")
    if existing_block is not None:
        existing_block.decompose()

    fragment = BeautifulSoup(reading_path_html, "html.parser")
    block = fragment.select_one("#reader-route")
    if block is None:
        return False

    source_texture = article_body.select_one("#source-texture")
    if source_texture is not None:
        source_texture.insert_after(block)
    else:
        first_section = article_body.find("section", recursive=False)
        if first_section is not None:
            first_section.insert_before(block)
        else:
            article_body.append(block)

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def inject_context_rail_into_article_page(target: Path) -> bool:
    if not target.exists():
        return False

    existing = target.read_text()
    if 'data-page-type="article"' not in existing:
        return False

    soup = BeautifulSoup(existing, "html.parser")
    page_shell = soup.select_one(".page-shell")
    layout = soup.select_one(".article-layout")
    main = soup.select_one(".article-layout > .article-stack")
    if page_shell is None or layout is None or main is None:
        return False

    changed = False
    if page_shell.get("id") != "top":
        page_shell["id"] = "top"
        changed = True

    layout_classes = layout.get("class") or []
    normalized_layout_classes = [
        item for item in layout_classes if item != "article-layout--single"
    ]
    if "article-layout--with-rail" not in normalized_layout_classes:
        normalized_layout_classes.append("article-layout--with-rail")
    if normalized_layout_classes != layout_classes:
        layout["class"] = normalized_layout_classes
        changed = True

    rail = layout.select_one("[data-context-rail]")
    if rail is None:
        rail = soup.new_tag("aside")
        rail["class"] = "context-rail-slot"
        rail["data-context-rail"] = ""
        main.insert_after(rail)
        changed = True
    else:
        rail_classes = rail.get("class") or []
        if "context-rail-slot" not in rail_classes:
            rail["class"] = [*rail_classes, "context-rail-slot"]
            changed = True

    if not changed:
        return False

    updated = str(soup)
    if updated == existing:
        return False
    target.write_text(updated)
    return True


def cleanup_auto_generated(valid_targets: set[Path]) -> None:
    for target in ROOT.rglob("index.html"):
        if target in valid_targets:
            continue
        if AUTO_MARKER not in target.read_text():
            continue
        target.unlink()
        parent = target.parent
        while parent != ROOT and not any(parent.iterdir()):
            parent.rmdir()
            parent = parent.parent


def sitemap_entry(path: str, lastmod: str, priority: str = "0.7") -> str:
    loc = html.escape(absolute_site_url(path), quote=False)
    return textwrap.dedent(
        f"""\
        <url>
          <loc>{loc}</loc>
          <lastmod>{lastmod}</lastmod>
          <changefreq>weekly</changefreq>
          <priority>{priority}</priority>
        </url>"""
    )


def write_robots_and_sitemap(generated_pages: list[dict]) -> None:
    today = date.today().isoformat()
    entries = [
        sitemap_entry("/", today, "1.0"),
        sitemap_entry("/search/", today, "0.8"),
        sitemap_entry("/guided-reading/", today, "0.8"),
        sitemap_entry("/concept-glossary/", today, "0.8"),
        sitemap_entry("/menu-structure/", today, "0.6"),
        *(sitemap_entry(f"/branches/{section_id}/", today, "0.7") for section_id in SECTION_IDS),
    ]
    for page in sorted(generated_pages, key=lambda item: item["built_path"]):
        path = normalize_site_path(page["built_path"])
        if not page_is_indexable(path):
            continue
        lastmod = page.get("date", "")[:10] or today
        entries.append(sitemap_entry(path, lastmod, "0.8"))

    sitemap = "\n".join(
        [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
            *entries,
            "</urlset>",
            "",
        ]
    )
    robots = textwrap.dedent(
        f"""\
        User-agent: *
        Allow: /
        Disallow: /quality/
        Disallow: /quality-review/
        Disallow: /recent-posts-expanded-version/
        Disallow: /byteseismic-podcasts/

        Sitemap: {SITE_ORIGIN}/sitemap.xml
        """
    )
    (ROOT / "sitemap.xml").write_text(sitemap)
    (ROOT / "robots.txt").write_text(robots)


def node_to_topic_tree(nodes: list[dict]) -> list[dict]:
    tree = []
    for node in nodes:
        entry = {"title": clean_page_title(node["title"])}
        if node.get("built_path"):
            entry["path"] = node["built_path"]
        if node.get("children"):
            entry["children"] = node_to_topic_tree(node["children"])
        tree.append(entry)
    return tree


def flatten_visible_nodes(nodes: list[dict]) -> list[dict]:
    flat = []
    for node in nodes:
        flat.append(node)
        flat.extend(flatten_visible_nodes(node.get("children", [])))
    return flat


def main() -> None:
    home_html = fetch_homepage_html()
    section_nodes = section_nodes_from_home(home_html)
    augment_section_hierarchy(section_nodes)
    augment_philosopher_hierarchy(section_nodes)
    all_posts = fetch_all_posts()

    visible_lookup: dict[str, dict] = {}
    for section_id, nodes in section_nodes.items():
        visible_lookup.update(hierarchy_lookup(nodes, section_id))

    posts_by_url = {canonical_url(post["URL"]): post for post in all_posts if post.get("URL")}
    generated_pages: list[dict] = []
    page_index: dict[tuple[str, str], dict] = {}

    def register_page(
        title: str,
        section_id: str,
        built_path: str,
        source_url: str = "",
        post: dict | None = None,
        children: list[dict] | None = None,
        sibling_titles: list[str] | None = None,
        parent_titles: list[str] | None = None,
    ) -> dict:
        title = clean_page_title(title)
        key = (section_id, built_path)
        if key in page_index:
            page = page_index[key]
            if children is not None:
                page["children"] = children
            if sibling_titles is not None:
                page["sibling_titles"] = sibling_titles
            if parent_titles is not None:
                page["parent_titles"] = parent_titles
            return page

        page_kind = infer_kind(title, bool(children))
        source_prompts, thread_like, _paragraphs = ([], [], [])
        source_prompt_details: list[dict] = []
        dialogue_sections: dict[str, dict] = {}
        chart_tables: list[dict] = []
        quiz_discussion_items: list[str] = []
        special_payload: dict | None = None
        if post:
            source_prompts, thread_like, _paragraphs = normalize_heading_list(
                post.get("content", ""),
                clean_text(title),
            )
            quiz_discussion_items = extract_quiz_discussion_items(
                post.get("content", ""),
                clean_text(title),
            )
            source_prompt_details = extract_source_prompt_details(
                post.get("content", ""),
                clean_text(title),
            )
            source_prompt_details = [
                detail for detail in source_prompt_details if should_keep_source_prompt_detail(detail)
            ]
            if source_prompt_details:
                source_prompts = [detail["prompt"] for detail in source_prompt_details]
            if page_kind == "dialogue":
                dialogue_sections = extract_original_dialogue_sections(
                    post.get("content", ""),
                    clean_text(title),
                )
            if page_kind == "chart":
                chart_tables = extract_original_chart_tables(
                    post.get("content", ""),
                    clean_text(title),
                )
        elif section_id == "philosophers":
            thread_like = synthetic_philosopher_threads(title)
            if page_kind not in {"dialogue", "chart"}:
                source_prompt_details = synthetic_philosopher_prompt_details(title)
                if source_prompt_details:
                    source_prompts = [detail["prompt"] for detail in source_prompt_details]
            if page_kind == "cluster" and philosopher_profile_for_title(title):
                page_kind = "essay"
        else:
            special_payload = special_synthetic_page_data(section_id, title)
            if special_payload:
                source_prompt_details = special_payload.get("source_prompt_details", [])
                if source_prompt_details:
                    source_prompts = [detail["prompt"] for detail in source_prompt_details]
                thread_like = special_payload.get("thread_like", thread_like)
                quiz_discussion_items = special_payload.get("quiz_discussion_items", quiz_discussion_items)
        page = {
            "title": clean_text(title),
            "section_id": section_id,
            "built_path": built_path,
            "source_url": source_url,
            "kind": page_kind,
            "source_prompts": source_prompts,
            "source_prompt_details": source_prompt_details,
            "dialogue_sections": dialogue_sections,
            "chart_tables": chart_tables,
            "quiz_discussion_items": quiz_discussion_items,
            "thread_like": thread_like,
            "excerpt": strip_html(post.get("excerpt", "") if post else ""),
            "source_text": strip_html(post.get("content", "") if post else ""),
            "date": post.get("date", "") if post else "",
            "children": children or [],
            "sibling_titles": sibling_titles or [],
            "parent_titles": parent_titles or [],
        }
        if not post and special_payload:
            page["excerpt"] = special_payload.get("excerpt", page["excerpt"])
        page_index[key] = page
        generated_pages.append(page)
        return page

    def assign_visible_paths(
        section_id: str,
        nodes: list[dict],
        siblings: list[str] | None = None,
        parents: list[str] | None = None,
    ) -> None:
        sibling_titles = siblings or [node["title"] for node in nodes]
        parent_titles = parents or []
        for node in nodes:
            href = node.get("href", "")
            canonical = canonical_url(href) if href and "byteseismic.com" in href else ""
            post = posts_by_url.get(canonical)
            synthetic = not post and (not href or "wordpress.com" in href or "#" in href)
            built_path = build_path_for_node(section_id, node["title"], source_url=href, synthetic=synthetic)
            node["built_path"] = built_path
            if post:
                register_page(
                    title=node["title"],
                    section_id=section_id,
                    built_path=built_path,
                    source_url=canonical,
                    post=post,
                    children=node.get("children", []),
                    sibling_titles=sibling_titles,
                    parent_titles=parent_titles,
                )
            else:
                register_page(
                    title=node["title"],
                    section_id=section_id,
                    built_path=built_path,
                    source_url=canonical or href,
                    children=node.get("children", []),
                    sibling_titles=sibling_titles,
                    parent_titles=parent_titles,
                )
            if node.get("children"):
                assign_visible_paths(
                    section_id,
                    node["children"],
                    [child["title"] for child in node["children"]],
                    parent_titles + [node["title"]],
                )

    for section_id, nodes in section_nodes.items():
        assign_visible_paths(section_id, nodes)

    visible_urls = {canonical_url(post["URL"]) for post in all_posts if canonical_url(post["URL"]) in visible_lookup}

    for post in all_posts:
        canonical = canonical_url(post["URL"])
        if canonical in visible_urls:
            continue
        override = FEATURED_PATHS_BY_TITLE.get(clean_text(post["title"]).lower())
        if override:
            section_id, built_path = override
        else:
            section_id = classify_section(post)
            built_path = f"/{section_id}/{slugify(post['slug'])}/"
        register_page(
            title=clean_text(post["title"]),
            section_id=section_id,
            built_path=built_path,
            source_url=canonical,
            post=post,
        )

    generated_pages.sort(key=lambda item: (item["section_id"], item["title"].lower()))

    global RENDER_PAGE_PATHS_BY_SECTION_TITLE
    RENDER_PAGE_PATHS_BY_SECTION_TITLE = {
        (page["section_id"], clean_page_title(page["title"])): page["built_path"]
        for page in generated_pages
    }

    valid_targets: set[Path] = set()
    for page in generated_pages:
        if page["built_path"] in GROUP_PAGE_TITLES.values():
            continue
        target = ROOT / page["built_path"].strip("/") / "index.html"
        valid_targets.add(target)
        page["quality_tracked"] = write_if_allowed(target, render_article_page(page))
        if not page["quality_tracked"]:
            inject_dialectical_turn_into_manual_page(target, page)
            inject_quiz_into_manual_page(target, page)
            inject_seo_into_manual_page(target, page)
            inject_page_signals_into_manual_page(target, page)
            inject_philosopher_source_texture_into_manual_page(target, page)
            normalize_manual_breadcrumbs(target, page)
            normalize_manual_prompt_system(target)
            inject_reading_path_into_manual_page(target, page)
            inject_learning_cards_into_manual_page(target, page)
            inject_context_rail_into_article_page(target)

    menu_target = ROOT / "menu-structure" / "index.html"
    search_target = ROOT / "search" / "index.html"
    guided_target = ROOT / "guided-reading" / "index.html"
    glossary_target = ROOT / "concept-glossary" / "index.html"
    podcast_target = ROOT / "byteseismic-podcasts" / "index.html"
    archive_target = ROOT / "recent-posts-expanded-version" / "index.html"
    valid_targets.update({menu_target, search_target, guided_target, glossary_target, podcast_target, archive_target})

    write_if_allowed(menu_target, render_menu_structure_page())
    write_if_allowed(search_target, render_search_page())
    write_if_allowed(guided_target, render_guided_reading_page())
    write_if_allowed(glossary_target, render_glossary_page())
    write_if_allowed(podcast_target, render_podcast_page())

    for section_id in SECTION_IDS:
        branch_target = ROOT / "branches" / section_id / "index.html"
        valid_targets.add(branch_target)
        write_if_allowed(branch_target, render_branch_guide_page(section_id, generated_pages))

    posts_by_year: dict[int, list[dict]] = defaultdict(list)
    section_counts: dict[str, int] = defaultdict(int)
    for page in generated_pages:
        if not page["date"]:
            continue
        year = int(page["date"][:4])
        posts_by_year[year].append(page)
        section_counts[page["section_id"]] += 1

    write_if_allowed(archive_target, render_expanded_archive_page(posts_by_year, section_counts))

    quality_report = build_quality_report(generated_pages)
    quality_target = ROOT / "quality-review" / "index.html"
    valid_targets.add(quality_target)
    write_quality_files(quality_report)
    write_if_allowed(quality_target, render_quality_review_page(quality_report))
    visible_tags_by_path = visible_tag_chips_by_path(valid_targets)

    def choose_featured_pages() -> list[dict]:
        chosen = []
        seen_sections = set()
        path_lookup = {page["built_path"]: page for page in generated_pages}
        for spec in FEATURED_PAGE_SPECS:
            page = path_lookup.get(spec["path"])
            section_meta = SECTION_META[spec["section_id"]]
            if page is None:
                pseudo_page = {
                    "title": spec["title"],
                    "section_id": spec["section_id"],
                    "kind": infer_kind(spec["title"], False),
                }
                chosen.append(
                    {
                        "title": spec["title"],
                        "section": section_meta["name"],
                        "path": spec["path"],
                        "summary": feature_summary(pseudo_page, section_meta),
                        "tags": discovery_tag_candidates(pseudo_page, section_meta),
                    }
                )
                seen_sections.add(spec["section_id"])
                continue

            chosen.append(
                {
                    "title": page["title"],
                    "section": section_meta["name"],
                    "path": spec["path"],
                    "summary": feature_summary(page, section_meta),
                    "tags": discovery_tag_candidates(page, section_meta),
                }
            )
            seen_sections.add(spec["section_id"])
        for section_id in SECTION_IDS:
            if section_id in seen_sections:
                continue
            section_pages = [page for page in generated_pages if page["section_id"] == section_id]
            if not section_pages:
                continue
            page = section_pages[0]
            section_meta = SECTION_META[section_id]
            chosen.append(
                {
                    "title": page["title"],
                    "section": section_meta["name"],
                    "path": page["built_path"],
                    "summary": feature_summary(page, section_meta),
                    "tags": discovery_tag_candidates(page, section_meta),
                }
            )
        return chosen

    featured_pages = choose_featured_pages()
    glossary_tags_by_path: dict[str, list[str]] = defaultdict(list)
    for entry in GLOSSARY_TERMS:
        for path in entry.get("paths", []):
            glossary_tags_by_path[normalize_site_path(path)].extend(
                canonical
                for canonical in (canonical_tag_key(tag) for tag in entry.get("tags", []))
                if canonical
            )

    tagged_pages = []
    tag_archive_pages = []
    for page in generated_pages:
        if page["built_path"] in GROUP_PAGE_TITLES.values():
            continue
        section_meta = SECTION_META[page["section_id"]]
        discovery_tags = discovery_tag_candidates(page, section_meta)
        tagged_pages.append(
            {
                "title": page["title"],
                "section": section_meta["name"],
                "path": page["built_path"],
                "summary": feature_summary(page, section_meta),
                "tags": discovery_tags,
            }
        )
        tag_archive_pages.append(
            {
                "title": page["title"],
                "section": section_meta["name"],
                "path": page["built_path"],
                "summary": feature_summary(page, section_meta),
                "tags": dedupe(
                    discovery_tags
                    + visible_tags_by_path.get(page["built_path"], [])
                    + glossary_tags_by_path.get(page["built_path"], [])
                ),
            }
        )
    tag_counts: dict[str, int] = defaultdict(int)
    for page in tagged_pages:
        for tag in page["tags"]:
            tag_counts[tag] += 1
    tag_archive_counts: dict[str, int] = defaultdict(int)
    for page in tag_archive_pages:
        for tag in page["tags"]:
            tag_archive_counts[tag] += 1
    landing_tags = build_landing_tags(tag_counts)

    tag_pages = {
        tag: tag_page_path(tag)
        for tag in sorted(tag_archive_counts)
        if tag_archive_counts.get(tag, 0)
    }
    for tag, path in tag_pages.items():
        tag_target = ROOT / path.strip("/") / "index.html"
        valid_targets.add(tag_target)
        write_if_allowed(tag_target, render_tag_archive_page(tag, tag_archive_pages, tag_archive_counts))

    topic_paths = {
        "Site Map": "/menu-structure/",
        "Search": "/search/",
        "Guided Reading Paths": "/guided-reading/",
        "Concept Glossary": "/concept-glossary/",
        "Recent Posts — Expanded Version": "/recent-posts-expanded-version/",
    }
    for section_id in SECTION_IDS:
        topic_paths[f"{SECTION_META[section_id]['name']} Branch Guide"] = f"/branches/{section_id}/"
    for spec in FEATURED_PAGE_SPECS:
        topic_paths[spec["title"]] = spec["path"]
    sections_data = []
    for section_id in SECTION_IDS:
        meta = SECTION_META[section_id]
        nodes = section_nodes.get(section_id, [])
        topic_tree = node_to_topic_tree(nodes)
        flat_nodes = flatten_visible_nodes(nodes)
        for node in flat_nodes:
            if node.get("built_path"):
                topic_paths[clean_page_title(node["title"])] = node["built_path"]
        visible_titles = [clean_page_title(node["title"]) for node in flat_nodes]
        sample_path = meta.get("preferredPath")
        if not sample_path and flat_nodes:
            sample_path = flat_nodes[0].get("built_path")
        sections_data.append(
            {
                "id": section_id,
                "name": meta["name"],
                "summary": meta["summary"],
                "editorialIntro": branch_profile(section_id)["stakes"],
                "route": branch_profile(section_id)["route"],
                "coreTensions": branch_profile(section_id)["items"][:4],
                "seedTopics": visible_titles[:8],
                "topicCount": len(visible_titles),
                "futureTags": meta["futureTags"],
                "samplePath": sample_path,
                "branchGuidePath": f"/branches/{section_id}/",
                "topicTree": topic_tree,
            }
        )

    core_data = {
        "siteTitle": SITE_TITLE,
        "siteTagline": SITE_TAGLINE,
        "tagMeta": {
            tag: {
                "label": tag_display_label(tag),
                "kind": CONTROLLED_TAG_META.get(tag, {}).get("kind", "concept"),
            }
            for tag in sorted(curated_tag_vocabulary())
        },
        "tagCounts": dict(sorted(tag_counts.items())),
        "tagPages": tag_pages,
        "taggedPages": [
            {
                "title": page["title"],
                "section": page["section"],
                "path": page["path"],
                "tags": page["tags"],
            }
            for page in tagged_pages
        ],
        "topicPaths": topic_paths,
        "sections": sections_data,
    }
    search_data = {
        "featuredPages": featured_pages,
        "guidedReadingPaths": GUIDED_READING_PATHS,
        "glossaryTerms": GLOSSARY_TERMS,
        "landingTags": landing_tags,
        "taggedPages": tagged_pages,
    }
    site_core_js = "window.BYTESEISMIC_DATA=" + json.dumps(core_data, separators=(",", ":"), ensure_ascii=False) + ";\n"
    site_search_js = "window.BYTESEISMIC_SEARCH_DATA=" + json.dumps(search_data, separators=(",", ":"), ensure_ascii=False) + ";\n"
    (ROOT / "assets" / "js" / "site-core.js").write_text(site_core_js)
    (ROOT / "assets" / "js" / "site-search.js").write_text(site_search_js)
    legacy_site_data = ROOT / "assets" / "js" / "site-data.js"
    if legacy_site_data.exists():
        legacy_site_data.unlink()
    for target in valid_targets:
        link_static_tag_chips(target)
    cleanup_auto_generated(valid_targets)
    write_robots_and_sitemap(generated_pages)
    subprocess.run([sys.executable, str(ROOT / "scripts" / "site_audit.py")], check=True)

    print(f"Generated or updated {len(generated_pages)} content pages.")
    print(f"Visible hierarchy sections: {len(section_nodes)}")
    print(f"Expanded archive years: {len(posts_by_year)}")


if __name__ == "__main__":
    main()
